export const EditReportResponse = Schema.Struct({ "report_id": Schema.String.annotate({ "description": "Id of the edited report." }), "updated_fields": Schema.Array(Schema.String).annotate({ "description": "Which presentation fields changed (e.g. `title`, `summary`); empty if only a note was appended." }), "note_appended": Schema.Boolean.annotate({ "description": "Whether the edit included a note. True for a collapsed corroboration too, where the report's count moves and no work-log entry is written. Read `corroboration_collapsed` to tell the two apart." }), "evidence_appended": Schema.Number.annotate({ "description": "How many observations this edit added to the report's evidence rail; 0 if none." }).check(Schema.isInt()), "links_appended": Schema.Number.annotate({ "description": "How many typed report-to-report links this edit wrote; 0 if none." }).check(Schema.isInt()), "reviewers_set": Schema.Boolean.annotate({ "description": "Whether the report's suggested reviewers were replaced." }), "repository_set": Schema.Boolean.annotate({ "description": "Whether the report's repository was replaced (true for a cleared target too)." }), "repository": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "The repository the report points at now, read back from the report rather than echoed from the request; null when the report has no target. Compare it with the `repository` you sent to confirm the correction landed." }), "charts_set": Schema.Union([Schema.Number.check(Schema.isInt()), Schema.Null]).annotate({ "description": "How many charts the report now shows, or null if the edit left its charts as they were (the field omitted, or a re-send of what was already stored). 0 means the edit took the report's charts down." }), "metrics_set": Schema.Union([Schema.Number.check(Schema.isInt()), Schema.Null]).annotate({ "description": "How many impact metrics the report now shows, or null when untouched/unchanged. 0 means the edit removed every metric." }), "suggested_prompts_set": Schema.Union([Schema.Number.check(Schema.isInt()), Schema.Null]).annotate({ "description": "How many prompts the report now suggests, or null if the edit left them as they were (the field omitted, or a re-send of what was already stored). 0 means the edit took the report's suggested prompts down." }), "is_content_revision": Schema.Boolean.annotate({ "description": "Whether this edit actually rewrote the report's title or summary. False for a note, a reviewer change, or a re-send of the text the report already had." }), "content_revision_count": Schema.Number.annotate({ "description": "How many times a scout has rewritten this report's title or summary, counting this edit." }).check(Schema.isInt()), "supersedes_implementation": Schema.Boolean.annotate({ "description": "Whether the edit recorded that the report's pull request should be replaced. False when you did not ask for it, when the edit changed no content, or when the report has already been rewritten too many times." }), "corroboration_collapsed": Schema.Boolean.annotate({ "description": "Whether your note raised the report's corroboration count instead of landing as its own entry. Only notes marked corroboration_only can collapse; free-form notes remain in the work log." }) })
