export const FileDownloadCountRowsRequest = Schema.Struct({ "model": Schema.Literal("hogql").annotate({ "description": "* `hogql` - hogql" }), "hogql_query": Schema.String.annotate({ "description": "HogQL SELECT query whose results are exported. This model is in closed beta and is enabled per team; when it is not enabled, the request fails with a permission error that names HogQL batch exports. Contact PostHog support to request access. The query may reference the {data_interval_start} and {data_interval_end} placeholders. Provide a value for each placeholder the query references; missing referenced bounds are rejected, not inferred. When both bounds are supplied, they must span at most seven days. Neither supplied bound may be in the future. Without placeholders, the query runs unchanged, even if bounds are supplied. Every column in the SELECT clause must be a field or have an alias. It is recommended to limit the query with a WHERE clause, for example bounding timestamp on the events table, both to avoid exporting more rows than expected and because user queries run under stricter resource limits than the other models." }), "data_interval_start": Schema.optionalKey(Schema.String.annotate({ "description": "Start of the export interval. Required for the events, persons, and sessions models. For HogQL, required only when the query references {data_interval_start}. A supplied start must not be in the future. When both bounds are supplied, the interval must span at most seven days.", "format": "date-time" })), "data_interval_end": Schema.optionalKey(Schema.String.annotate({ "description": "End of the export interval. Required for the events, persons, and sessions models. For HogQL, required only when the query references {data_interval_end}. A supplied end must not be in the future or precede a supplied start. Bounds replace HogQL placeholders; they do not add filters to the query.", "format": "date-time" })) }).annotate({ "description": "Request shape for counting the rows a file download batch export would produce." })
