export const FlagApprovalConflict = Schema.Struct({ "code": Schema.String.annotate({ "description": "`approval_required` when this call opened the change request, `change_request_pending` when one was already open for the same action." }), "status": Schema.String.annotate({ "description": "Always `approval_required`." }), "detail": Schema.String.annotate({ "description": "Human-readable description of the policy that gated the change." }), "message": Schema.String.annotate({ "description": "Same text as `detail`." }), "resource_type": Schema.String.annotate({ "description": "Resource the change request targets, `feature_flag` here." }), "resource_id": Schema.String.annotate({ "description": "Id of the flag the change request targets." }), "change_request_id": Schema.String.annotate({ "description": "Id of the change request that was opened." }), "change_request": Schema.Json.annotate({ "description": "The change request that was opened, serialized in full." }), "required_approvers": Schema.Json.annotate({ "description": "Who can approve the change request." }) }).annotate({ "description": "The 409 body an approval policy produces, which differs from every other error here.\n\nRaised through the approvals mixin rather than the exception handler, so it carries the\nchange request it opened instead of the `type`/`attr` envelope." })
