export const FlakyTestItem = Schema.Struct({ "runner": Schema.Literals(["pytest", "jest"]).annotate({ "description": "* `pytest` - PYTEST\n* `jest` - JEST" }), "nodeid": Schema.String.annotate({ "description": "Runner-specific stable test identity (the CI span name). This is a grouping key, not necessarily runnable; use `selector` to run or quarantine the test." }), "selector": Schema.String.annotate({ "description": "Runnable pytest or Jest selector. Exact when the CI reporter emitted it; older pytest spans use a best-effort reconstruction from the nodeid." }), "classification": Schema.Literals(["confirmed_flake", "suspected_regression", "quarantined"]).annotate({ "description": "* `confirmed_flake` - CONFIRMED_FLAKE\n* `suspected_regression` - SUSPECTED_REGRESSION\n* `quarantined` - QUARANTINED" }), "same_commit_recovery_run_count": Schema.Number.annotate({ "description": "Runs where one commit both failed and passed the test: a 'Re-run failed jobs' attempt went green on the same commit, or an in-job pytest retry (tests hand-marked @pytest.mark.flaky(reruns=N)) recovered it. A pass in a different run is a different commit and never counts." }).check(Schema.isInt()), "failed_run_count": Schema.Number.annotate({ "description": "Distinct CI runs whose recorded outcome was failed or error. A run counts once however many matrix legs it failed in." }).check(Schema.isInt()), "failed_pr_count": Schema.Number.annotate({ "description": "Distinct pull requests among the failed runs. Failures on master or unattributed branches carry no PR number and are excluded here (still in failed_run_count)." }).check(Schema.isInt()), "master_failed_run_count": Schema.Number.annotate({ "description": "Failed runs on the default branch (master/main approximation): the 'matters right now' signal that a test is breaking the trunk, not just PR branches." }).check(Schema.isInt()), "quarantined_failed_run_count": Schema.Number.annotate({ "description": "Runs where the test recorded a tolerated failure while quarantined: already masked in CI, still failing." }).check(Schema.isInt()), "last_signal_at": Schema.String.annotate({ "description": "Most recent failure, recovery, or quarantined-failure run for this test in the window.", "format": "date-time" }) })
export type FleetFindingsSummary = { readonly "count": number, readonly "scout_count": number, readonly "authored_report_count": number, readonly "edited_report_count": number, readonly "run_count": number, readonly "latest_at": string }
export const FleetFindingsSummary = Schema.Struct({ "count": Schema.Number.annotate({ "description": "Total findings the fleet emitted in the window — the sum of each run's `emitted_count`, over the most recent 120 runs that produced output." }).check(Schema.isInt()), "scout_count": Schema.Number.annotate({ "description": "Number of distinct scouts (skills) that produced output in the window — emitted a finding, or authored/edited an inbox report that survives the 50-report cap (a report-only scout whose touched reports all fell outside the cap is not counted, matching the findings page's scout filter)." }).check(Schema.isInt()), "authored_report_count": Schema.Number.annotate({ "description": "Number of distinct inbox reports scouts authored via `emit_report`, deduped across runs, over the same most-recent-120-output-runs set as `count`, capped to the 50 most recently touched reports (the same slice the findings page lists)." }).check(Schema.isInt()), "edited_report_count": Schema.Number.annotate({ "description": "Number of distinct inbox reports scouts edited via `edit_report`, deduped across runs, over the same most-recent-120-output-runs set as `count`, capped to the 50 most recently touched reports (the same slice the findings page lists) and excluding reports also authored within that set (authoring supersedes an edit; a report whose authoring run falls outside the cap counts as edited)." }).check(Schema.isInt()), "run_count": Schema.Number.annotate({ "description": "Number of scout runs created in the window, whether or not they produced output. Unlike the report tallies it is not capped, so it is the fleet's activity over the same span the output counts describe." }).check(Schema.isInt()), "latest_at": Schema.Union([Schema.String.annotate({ "description": "ISO-8601 timestamp of the most recent output run (TaskRun completion, falling back to run creation), or null when nothing was produced in the window.", "format": "date-time" })]) }).annotate({ "description": "Fleet-wide tally of recent scout output — legacy `emit_signal` findings plus reports\nauthored/edited via the report channel. Backs the \"Scout findings\" callout so it renders\nfrom one cheap query instead of the client walking the whole paginated runs window." })
