export const LogsMetricRule = Schema.Struct({ "id": Schema.String.annotate({ "description": "Unique identifier for this metric rule.", "readOnly": true, "format": "uuid" }), "name": Schema.String.annotate({ "description": "User-visible label for this rule." }).check(Schema.isMaxLength(255)), "metric_name": Schema.String.annotate({ "description": "Name of the generated metric as it appears in the Metrics product. Must start with a letter and contain only letters, digits, dots, underscores, and dashes. Unique per project and immutable after creation — create a new rule to emit under a different name." }).check(Schema.isMaxLength(200)), "enabled": Schema.optionalKey(Schema.Boolean.annotate({ "description": "When true, ingestion evaluates this rule against every log record. At most 10 rules can be enabled per project.", "default": false })), "filter_group": Schema.optionalKey(Schema.Json.annotate({ "description": "PropertyGroupFilter JSON (AND/OR tree of property predicates) selecting which log records feed the metric, e.g. `{\"type\":\"AND\",\"values\":[{\"type\":\"AND\",\"values\":[{\"key\":\"service.name\",\"operator\":\"exact\",\"value\":\"api\",\"type\":\"log_attribute\"}]}]}`. Null matches every ingested log record. Every group must contain at least one filter — empty groups never match." })), "value_attribute": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxLength(512, { "description": "Attribute key holding a numeric value to aggregate into a distribution (count + sum), e.g. `attributes.duration_ms` or `resource_attributes.batch.size`, prefixed with `attributes.` / `resource_attributes.`. For `source=spans` rules, the span pseudo-key `duration_ms` (span wall-clock duration) is also allowed. Omit to count matching records instead. Immutable after creation — it determines the emitted metric type." }))])), "group_by": Schema.optionalKey(Schema.Array(Schema.String.check(Schema.isMaxLength(512))).annotate({ "description": "Up to 5 dimension keys; each distinct value combination becomes its own metric series. For `source=logs` rules allowed: service_name, severity_text, event_name; for `source=spans` rules allowed: service_name, name, status_code, kind; for either, map keys prefixed with `attributes.` / `resource_attributes.`. Avoid high-cardinality keys (user IDs, request IDs) — excess series are dropped at ingestion. For `source=spans` rules, note that `name` is high-cardinality on poorly instrumented services (route params or SQL fragments in the span name), so grouping by `name` can overflow the per-rule series cap on its own." })), "source": Schema.optionalKey(Schema.Literals(["logs", "spans"]).annotate({ "description": "* `logs` - Logs\n* `spans` - Spans", "default": "logs" })), "version": Schema.Number.annotate({ "description": "Incremented on each update for worker cache coherency.", "readOnly": true }).check(Schema.isInt()), "created_by": Schema.Number.annotate({ "readOnly": true }).check(Schema.isInt()), "created_at": Schema.String.annotate({ "readOnly": true, "format": "date-time" }), "updated_at": Schema.Union([Schema.String.annotate({ "readOnly": true, "format": "date-time" })]) })
