export const LogsRetentionRule = Schema.Struct({ "id": Schema.String.annotate({ "description": "Unique identifier for this retention rule.", "readOnly": true, "format": "uuid" }), "name": Schema.String.annotate({ "description": "User-visible label for this rule." }).check(Schema.isMaxLength(255)), "enabled": Schema.optionalKey(Schema.Boolean.annotate({ "description": "When false, the rule is ignored by ingestion and listing UIs that show active rules only.", "default": false })), "priority": Schema.optionalKey(Schema.Union([Schema.Number.check(Schema.isInt()).check(Schema.makeFilterGroup([Schema.isFinite(), Schema.isGreaterThanOrEqualTo(0)], { "description": "Lower numbers are evaluated first; the first matching rule wins. Omit to append after existing rules." }))])), "config": Schema.Json.annotate({ "description": "Retention rule JSON. Required keys: `retention_days` (integer — how long matching logs are kept; must be a tier the organization is entitled to, same as the team-wide Logs retention setting) and `filter_group` (PropertyGroupFilter shape — an AND/OR tree of property predicates evaluated per record to decide which logs this rule matches). Example: `{\"retention_days\":30,\"filter_group\":{\"type\":\"AND\",\"values\":[{\"type\":\"AND\",\"values\":[{\"key\":\"service.name\",\"operator\":\"exact\",\"value\":\"api\"}]}]}}`. Logs matching no enabled rule keep the environment's default retention." }), "version": Schema.Number.annotate({ "description": "Incremented on each update for worker cache coherency.", "readOnly": true }).check(Schema.isInt()), "created_by": Schema.Number.annotate({ "readOnly": true }).check(Schema.isInt()), "created_at": Schema.String.annotate({ "readOnly": true, "format": "date-time" }), "updated_at": Schema.Union([Schema.String.annotate({ "readOnly": true, "format": "date-time" })]) })
