export type PromptEvaluationResult = { readonly "session_id": string, readonly "observation_id": string, readonly "rated_correct": boolean, readonly "before": string | null, readonly "after": string | null, readonly "outcome": string, readonly "error": string | null }
export const PromptEvaluationResult = Schema.Struct({ "session_id": Schema.String.annotate({ "description": "The rated session that was re-run with the suggested prompt." }), "observation_id": Schema.String.annotate({ "description": "The original rated observation the comparison is against." }), "rated_correct": Schema.Boolean.annotate({ "description": "The team's rating of the original output (thumbs up = true)." }), "before": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "The original output's primary outcome." }), "after": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "The suggested prompt's outcome for the same session. Null when the run errored or returned no discrete outcome (e.g. a classifier with no tags)." }), "outcome": Schema.String.annotate({ "description": "kept (up, unchanged), regressed (up, changed), fixed (down, changed), still_wrong (down, unchanged), error, or preview (scorer/summarizer: raw before/after, no classification)." }), "error": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Why this session's re-run failed, when it did." }) })
export type PromptEvaluationSummary = { readonly "kept": number, readonly "regressed": number, readonly "fixed": number, readonly "still_wrong": number, readonly "errors": number }
