export const RememberRequest = Schema.Struct({ "key": Schema.String.annotate({ "description": "Agent-chosen semantic key, unique per team; re-using a key overwrites the entry in place. Key off the *stable identity* of what you're tracking — never embed a date, timestamp, or run id (that mints a new row every run and breaks dedupe). For run state/cursors, use one fixed key and keep the timestamp in `content`." }).check(Schema.isMaxLength(300)), "content": Schema.String.annotate({ "description": "Prose to write. Read verbatim into future prompts." }).check(Schema.isMaxLength(50000)), "run_id": Schema.optionalKey(Schema.Union([Schema.String.annotate({ "description": "Run that authored this memory; persisted as `created_by_run_id` for lineage. Best-effort — a `run_id` that is unparseable, or that isn't a run on this project, is dropped rather than rejected, so the memory write is never lost. Omit it and the lineage still lands: a write from a scout sandbox is attributed to that sandbox's own run.", "format": "uuid" })])), "expires_at": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Optional ISO-8601 expiry for a memory that's only true for a while (a cooldown, a window you're watching). After this time the entry drops out of searches, so you don't have to come back and forget it. Omit for a durable memory — every write sets the whole entry, so omitting it on a later write clears an expiry set earlier. Best-effort — a value that can't be parsed or is already in the past is dropped (the memory stays durable), not rejected, so the memory write is never lost." })) }).annotate({ "description": "Request body for `remember`." })
