export type ScoutCost = { readonly "skill_name": string, readonly "spend_usd": number, readonly "run_count": number, readonly "priced_run_count": number, readonly "reports_touched": number }
export const ScoutCost = Schema.Struct({ "skill_name": Schema.String.annotate({ "description": "Full skill name of the scout, e.g. `signals-scout-error-tracking`." }), "spend_usd": Schema.Number.annotate({ "description": "Model spend attributed to the scout's runs in the window, in US dollars. Zero when none of its runs had spend attributed, which `priced_run_count` tells apart from a scout that really spent nothing.", "format": "double" }).check(Schema.isFinite()), "run_count": Schema.Number.annotate({ "description": "Runs the scout started in the window." }).check(Schema.isInt()), "priced_run_count": Schema.Number.annotate({ "description": "Runs of the scout that had spend attributed. Lower than `run_count` where a run failed before its first model call, or its generations haven't landed yet. Divide `spend_usd` by this, not by `run_count`, for cost per run." }).check(Schema.isInt()), "reports_touched": Schema.Number.annotate({ "description": "Distinct inbox reports the scout filed or added to in the window. A report it authored in one run and edited in three counts once. Zero means the scout produced no reports, so cost per report has no value rather than a value of zero." }).check(Schema.isInt()) }).annotate({ "description": "What one scout spent in the window, and what it produced for that spend." })
