export const ScoutFleetEntry = Schema.Struct({ "skill_name": Schema.String.annotate({ "description": "The skill this config schedules as a scout." }), "run_interval_minutes": Schema.Number.annotate({ "description": "Minutes between runs when no cron schedule is set (default 1440, every 24 hours)." }).check(Schema.isInt()), "run_cron_schedule": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Optional cron expression, evaluated in the project timezone. Takes precedence over the interval." }), "emit": Schema.Boolean.annotate({ "description": "Whether this scout's findings actually reach the inbox. False means dry-run: it runs and logs but emits nothing, so its silence says nothing about the surface it watches." }), "last_run_at": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "ISO-8601 timestamp the coordinator last dispatched this scout, or null if it has never run." }), "last_emitted_at": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "ISO-8601 timestamp this scout last produced output on either channel (a finding, or an authored/edited report), within `emitted_lookback_days`. Null means quiet for at least that window, not never." }), "not_running_reason": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Why this scout is in the `disabled` bucket: `turned_off` (a person or seed posture set it off), `auto_paused` (the system paused it), or `skill_unavailable` (left on, but its skill was deleted, superseded, or withheld, so it never dispatches). Null for scouts that actually run." }), "pause_reason": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "The cause behind an `auto_paused` entry: `no_output`, `ignored`, or `repeated_failures`. Null for every other entry." }) }).annotate({ "description": "One scout in either bucket of `inventory.scout_fleet`." })
