export type ScoutNote = { readonly "id": string, readonly "skill_name": string, readonly "content": string, readonly "created_at": string | null, readonly "expires_at": string | null, readonly "created_by_name": string | null, readonly "origin": string }
export const ScoutNote = Schema.Struct({ "id": Schema.String.annotate({ "description": "Note UUID. Pass to `scout-notes-delete` to retire the note." }), "skill_name": Schema.String.annotate({ "description": "Who the note is addressed to: a configured scout's skill name, a pipeline audience (`pipeline:*`, e.g. `pipeline:report-research`), or blank for a general note every scout sees." }), "content": Schema.String.annotate({ "description": "The note's prose, read verbatim by the run that picks it up." }), "created_at": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "ISO-8601 creation timestamp." }), "expires_at": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "ISO-8601 expiry, or null for a note that stays active until deleted." }), "created_by_name": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Display name of the user who left the note, or null when unavailable." }), "origin": Schema.String.annotate({ "description": "Where the note came from. `human` for one left directly through this API. `report_dismissal` for one forwarded from the note someone typed when they dismissed, snoozed, or restored one or more inbox reports: one reviewer's verdict on the reports its content names, so weigh it as evidence about those reports rather than as fleet-level steering. `report_discussion` for the question someone asked when they opened a discussion on a report: context to weigh, neither a verdict on the report nor a directive. `report_feedback` for the note someone left when rating a report useful or not: one reader's rating of the named report, context to weigh rather than a directive. `report_reviewer_correction` for a suggested reviewer someone added or removed on a report: evidence about who owns that surface, and a prompt to revisit the routing memory it corrects, rather than a directive." }) }).annotate({ "description": "`SignalScoutNote` projection used by `notes-list` and `notes-create`." })
