export const ScoutNoteCreateRequest = Schema.Struct({ "content": Schema.String.annotate({ "description": "The note's prose — feedback, a pointer, or a nudge for the scout(s) to weigh on their next runs (e.g. 'we shipped a new checkout on Tuesday, watch conversion closely', 'stop flagging the staging traffic spike'). Write it in Markdown; the run reads it verbatim." }).check(Schema.isMaxLength(10000)), "skill_name": Schema.optionalKey(Schema.String.annotate({ "description": "Address the note to one scout by its skill name (exact match against a configured scout on the project — check `scout-config-list` for the roster), or to one stage of the report pipeline by its reserved audience (`pipeline:report-research`). Use a pipeline audience for guidance about how reports get researched rather than about what the scouts watch, so it reaches that stage and no scout. Omit or leave blank for a general note every scout sees." }).check(Schema.isMaxLength(200))), "expires_at": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Optional ISO-8601 expiry. After this time the note drops out of the default list view, so time-boxed steering ('watch closely this week') retires itself. Omit for a note that stays active until deleted. Best-effort — a value that can't be parsed or is already in the past is dropped (the note stays active), not rejected, so the note is never lost." })) }).annotate({ "description": "Request body for `notes-create`." })
