export const SignalReportBulkStateRequest = Schema.Struct({ "state": Schema.Literals(["suppressed", "potential", "resolved"]).annotate({ "description": "* `suppressed` - suppressed\n* `potential` - potential\n* `resolved` - resolved" }), "dismissal_reason": Schema.optionalKey(Schema.Literals(["already_fixed", "report_unclear", "analysis_wrong", "wrong_repo", "wontfix_intentional", "wontfix_irrelevant", "fixed_outside_posthog", "pr_merged", "other"]).annotate({ "description": "* `already_fixed` - Already fixed\n* `report_unclear` - Report is unclear to me\n* `analysis_wrong` - Agent's analysis is wrong\n* `wrong_repo` - Agent picked the wrong repository\n* `wontfix_intentional` - Won't fix - intentional behavior\n* `wontfix_irrelevant` - Won't fix - issue is real but insignificant\n* `fixed_outside_posthog` - Fixed outside PostHog\n* `pr_merged` - PR was merged\n* `other` - Something else…" })), "dismissal_note": Schema.optionalKey(Schema.String.annotate({ "description": "Optional free-form note explaining the dismissal. Capped at 4000 characters." }).check(Schema.isMaxLength(4000))), "corrected_repository": Schema.optionalKey(Schema.String.annotate({ "description": "Optional, only allowed with dismissal_reason='wrong_repo'. The repository this report should have targeted, in 'owner/repo' format (case-insensitive). It is recorded with the dismissal and fed into future repository selection for this project. When the repository is connected to the project, it also becomes the report's corrected repo selection, so restoring the report re-researches against it." }).check(Schema.isMinLength(1)).check(Schema.isMaxLength(140))), "snooze_for": Schema.optionalKey(Schema.Number.annotate({ "description": "Optional, only honored when state is 'potential'. Number of additional signals the report must accumulate before it is re-promoted into the pipeline — effectively snoozing it until then. Omit to let the report re-enter the pipeline on the next matching signal." }).check(Schema.isInt()).check(Schema.isGreaterThanOrEqualTo(1)).check(Schema.isLessThanOrEqualTo(100000))), "ids": Schema.Array(Schema.String.annotate({ "format": "uuid" })).annotate({ "description": "Report ids to transition to `state` in one call (1–100). Duplicates are de-duplicated; each id is processed independently so one disallowed transition does not block the rest. `dismissal_reason`, `dismissal_note`, `corrected_repository` and `snooze_for` apply to every id." }).check(Schema.isMaxLength(100)) })
