export const SignalScoutSlackDestination = Schema.Struct({ "integration_id": Schema.Number.annotate({ "description": "ID of the Slack integration whose bot posts this scout's findings and reports." }).check(Schema.isInt()).check(Schema.isGreaterThanOrEqualTo(1)), "channel": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxLength(255, { "description": "Slack channel target in the channel picker's `channel_id|#channel-name` format. Null while choosing a channel; no messages are sent until a channel or user is set." }))])), "users": Schema.optionalKey(Schema.Union([Schema.Array(Schema.String.check(Schema.isMaxLength(255)).check(Schema.isPattern(new RegExp("^[UW][A-Z0-9]{4,}\\s*(\\|.*)?$")))).check(Schema.makeFilterGroup([Schema.isMinLength(1), Schema.isMaxLength(5)], { "description": "Slack members to send output to as direct messages, each in `member_id|@display-name` format (a bare member ID like `U0123ABC456` also works). Each member gets their own DM from the PostHog app; at most 5. Set either this or `channel`, not both. Useful for personal scouts where a DM beats a channel." }))])), "thread_reports": Schema.optionalKey(Schema.Boolean.annotate({ "description": "When true, post a report as a thread: a short lead in the channel and the rest split into replies at the summary's section labels, which can be Markdown headings or bold labels. Keeps a long summary from being clipped at Slack's section limit. On by default; set it false to post a single message, which can truncate a long summary. It does not change how findings post.", "default": true })) })
