export const SpanTreeNode = Schema.Struct({ "avg_duration_nano": Schema.Number.annotate({ "title": "Avg Duration Nano" }).check(Schema.isFinite()), "avg_start_offset_nano": Schema.Number.annotate({ "title": "Avg Start Offset Nano", "description": "Average nanoseconds from the parent span's start to this span's start. Zero for root spans. Used to order children left-to-right by typical start time in the flame graph." }).check(Schema.isFinite()), "calls_per_parent_invocation": Schema.optionalKey(Schema.Union([Schema.Number.check(Schema.isFinite()), Schema.Null]).annotate({ "title": "Calls Per Parent Invocation", "description": "How many times this child runs per parent invocation (edge count / parent span count). Separates fan-out volume from per-call cost: a child can dominate total_duration_nano purely by running many times per parent. Null for root edges (no parent invocation to ratio against).", "default": null })), "count": Schema.Number.annotate({ "title": "Count" }).check(Schema.isInt()), "error_count": Schema.Number.annotate({ "title": "Error Count" }).check(Schema.isInt()), "name": Schema.String.annotate({ "title": "Name" }), "p50_duration_nano": Schema.Number.annotate({ "title": "P50 Duration Nano" }).check(Schema.isFinite()), "p95_duration_nano": Schema.Number.annotate({ "title": "P95 Duration Nano" }).check(Schema.isFinite()), "p999_duration_nano": Schema.Number.annotate({ "title": "P999 Duration Nano" }).check(Schema.isFinite()), "p99_duration_nano": Schema.Number.annotate({ "title": "P99 Duration Nano" }).check(Schema.isFinite()), "parent_name": Schema.String.annotate({ "title": "Parent Name" }), "parent_service": Schema.String.annotate({ "title": "Parent Service" }), "service_name": Schema.String.annotate({ "title": "Service Name" }), "total_duration_nano": Schema.Number.annotate({ "title": "Total Duration Nano" }).check(Schema.isFinite()) }).annotate({ "title": "SpanTreeNode" })
