export const StamphogInstallInfo = Schema.Struct({ "app_slug": Schema.String.annotate({ "description": "URL-friendly slug of the dedicated Stamphog GitHub App, or blank if unconfigured.", "readOnly": true }), "install_url": Schema.String.annotate({ "description": "GitHub install URL (github.com/apps/<slug>/installations/new) the 'Connect' button opens. The user picks a GitHub account there and chooses which repositories the App can reach, including an account where the App is already installed. Blank if the App slug is unconfigured.", "readOnly": true }), "authorize_url": Schema.String.annotate({ "description": "GitHub authorize URL (github.com/login/oauth/authorize). GitHub's redirect after configuring an existing installation carries no OAuth code, so the client passes through this URL once: an installed App redirects straight back with a code, which sync_installation uses to prove ownership. Blank if the App client id is unconfigured.", "readOnly": true }) }).annotate({ "description": "Static info the frontend needs to render the 'Connect a repository' button." })
