export const TeamTracingConfig = Schema.Struct({ "tracing_distinct_id_attribute_keys": Schema.Array(Schema.String.check(Schema.isMaxLength(200))).annotate({ "description": "Span or resource attribute keys whose values should match a person's distinct_id — a span links to a person when any of these attributes holds one of their distinct IDs. Defaults to ['posthogDistinctId'], the key the posthog-js / posthog-react-native SDKs attach to the OTel signals they emit. Add keys only if your pipeline emits the person identifier under different attributes." }).check(Schema.isMaxLength(10)), "tracing_session_id_attribute_keys": Schema.Array(Schema.String.check(Schema.isMaxLength(200))).annotate({ "description": "Ordered list of span or resource attribute keys whose values hold the PostHog session ID. Detection checks keys in order, then falls back to common session ID attribute conventions; the first key with a value wins. Defaults to ['sessionId'], the key the posthog-js / posthog-react-native SDKs attach to the OTel signals they emit. Add keys only if your pipeline emits the session ID under different attributes." }).check(Schema.isMaxLength(10)), "retention_days": Schema.optionalKey(Schema.Number.annotate({ "description": "How long spans are kept before they are deleted, in days. Applied at ingest, so a change only affects spans received after it. Can be changed at most once per 24 hours. Span retention rules override this period for the spans they match." }).check(Schema.isInt())), "retention_last_updated": Schema.Union([Schema.String.annotate({ "readOnly": true, "format": "date-time" })]) })
