export const TicketPerson = Schema.Struct({ "id": Schema.String.annotate({ "readOnly": true, "format": "uuid" }), "name": Schema.String.annotate({ "readOnly": true }), "distinct_ids": Schema.Array(Schema.String).annotate({ "readOnly": true }), "properties": Schema.Record(Schema.String, Schema.Json).annotate({ "readOnly": true }), "created_at": Schema.String.annotate({ "readOnly": true, "format": "date-time" }), "is_identified": Schema.Boolean.annotate({ "readOnly": true }) }).annotate({ "description": "Minimal person serializer for embedding in ticket responses." })
export type TicketPriorityEnum = "low" | "medium" | "high" | "critical"
export const TicketPriorityEnum = Schema.Literals(["low", "medium", "high", "critical"]).annotate({ "description": "* `low` - Low\n* `medium` - Medium\n* `high` - High\n* `critical` - Critical" })
export type TicketReplyRequest = { readonly "message": string, readonly "is_private"?: boolean, readonly "rich_content"?: Schema.Json }
export const TicketReplyRequest = Schema.Struct({ "message": Schema.String.annotate({ "description": "Reply content in markdown." }).check(Schema.isMaxLength(5000)), "is_private": Schema.optionalKey(Schema.Boolean.annotate({ "description": "If true, store as an internal note (not sent to the customer). If false, the reply is delivered to the customer over the ticket's channel.", "default": false })), "rich_content": Schema.optionalKey(Schema.Json.annotate({ "description": "Optional TipTap rich content JSON for formatted messages." })) }).annotate({ "description": "Payload for posting a reply or internal note to a ticket." })
