export const VisionQuota = Schema.Struct({ "credit_limit": Schema.Union([Schema.Number.check(Schema.isInt()), Schema.Null]).annotate({ "description": "Credits the organization may spend per billing period (1 credit = $0.01). 0 is a hard block: no observation can start. Null when billing has synced the product with no spend limit: uncapped.", "readOnly": true }), "credits_used": Schema.Number.annotate({ "description": "`credits_settled` plus `credits_reserved`: the organization's total draw on `credit_limit` this period, across every project.", "readOnly": true }).check(Schema.isInt()), "credits_settled": Schema.Number.annotate({ "description": "Credits posted to the receipt ledger by succeeded observations and finished prompt-test sessions this period, across every project in the organization. Deleting an observation never refunds these.", "readOnly": true }).check(Schema.isInt()), "credits_reserved": Schema.Number.annotate({ "description": "Credits held by in-flight observations and running prompt tests across every project in the organization. Released without charge when the work fails, settled into `credits_settled` when it succeeds.", "readOnly": true }).check(Schema.isInt()), "remaining": Schema.Union([Schema.Number.check(Schema.isInt()), Schema.Null]).annotate({ "description": "`credit_limit - credits_used`, floored at 0. Null when uncapped.", "readOnly": true }), "exhausted": Schema.Boolean.annotate({ "description": "True when `credits_used >= credit_limit`; further observations are skipped until next period. Always false when uncapped.", "readOnly": true }), "period_start": Schema.String.annotate({ "description": "First moment of the current quota period (UTC).", "readOnly": true, "format": "date-time" }), "period_end": Schema.String.annotate({ "description": "First moment of the next quota period (UTC); the current period's exclusive upper bound.", "readOnly": true, "format": "date-time" }), "projected_monthly_credits": Schema.Number.annotate({ "description": "`scanners_monthly_credits` plus `backfills_committed_credits`. Kept as the single headline number; prefer the two components when pro-rating, since only the scanner half is a monthly rate.", "readOnly": true }).check(Schema.isInt()), "scanners_monthly_credits": Schema.Number.annotate({ "description": "Credit-weighted sum of enabled scanners' projected observations/month across the organization. A capped scanner contributes at most what its own credit limit has left this period, folded back into a 30-day rate. A monthly rate: only the part falling in the days left of the period lands this period. Scanners without a computed estimate contribute 0.", "readOnly": true }).check(Schema.isInt()), "backfills_committed_credits": Schema.Number.annotate({ "description": "Committed-but-unspent credits of the organization's active backfills. A one-off charge rather than a rate, so it lands in full regardless of how much of the period is left.", "readOnly": true }).check(Schema.isInt()), "free_monthly_credits": Schema.Number.annotate({ "description": "Credits per period included for free. Already counted inside `credit_limit`; only credits beyond this number are billed.", "readOnly": true }).check(Schema.isInt()) })
