export const _BucketBreakdownRow = Schema.Struct({ "bucket_start": Schema.String.annotate({ "description": "UTC start of the time bucket the events fall in (`toStartOfInterval(timestamp, ...)`).", "format": "date-time" }), "event_count": Schema.Number.annotate({ "description": "Number of $ai_generation + $ai_embedding events in this bucket for the scoped product." }).check(Schema.isInt()), "cost_usd": Schema.Number.annotate({ "description": "Total cost in USD in this bucket (sum of `$ai_total_cost_usd`). Authoritative: the component columns below can sum to less than this when the cost breakdown was unavailable for some events; render any remainder as uncategorized rather than assuming the components reconcile.", "format": "double" }).check(Schema.isFinite()), "input_cost_usd": Schema.Number.annotate({ "description": "Cost of uncached (full-price) input tokens in USD, derived per event as `$ai_input_cost_usd` minus the cache read/write costs (the stored input cost includes them), clamped at zero. The four component columns are disjoint: they sum to `cost_usd` when the full breakdown is present, so they can be stacked without double counting cache costs.", "format": "double" }).check(Schema.isFinite()), "output_cost_usd": Schema.Number.annotate({ "description": "Cost of output tokens in USD (sum of `$ai_output_cost_usd`).", "format": "double" }).check(Schema.isFinite()), "cache_read_cost_usd": Schema.Number.annotate({ "description": "Cost of prompt-cache reads in USD (sum of `$ai_cache_read_cost_usd`).", "format": "double" }).check(Schema.isFinite()), "cache_creation_cost_usd": Schema.Number.annotate({ "description": "Cost of prompt-cache writes in USD (sum of `$ai_cache_creation_cost_usd`). A spike here with near-zero cache reads is the signature of a cold session being revived: the full conversation context is re-written to the cache at the cache-write rate instead of being read back cheaply.", "format": "double" }).check(Schema.isFinite()), "input_tokens": Schema.Number.annotate({ "description": "Sum of `$ai_input_tokens` in this bucket. Whether cached tokens are included follows the provider's reporting (`$ai_cache_reporting_exclusive`): Anthropic-style events exclude them, OpenAI-style events include them, so don't stack this with the cache token sums." }).check(Schema.isInt()), "output_tokens": Schema.Number.annotate({ "description": "Sum of `$ai_output_tokens` in this bucket." }).check(Schema.isInt()), "cache_read_input_tokens": Schema.Number.annotate({ "description": "Sum of `$ai_cache_read_input_tokens` (prompt tokens served from cache) in this bucket." }).check(Schema.isInt()), "cache_creation_input_tokens": Schema.Number.annotate({ "description": "Sum of `$ai_cache_creation_input_tokens` (prompt tokens written to cache) in this bucket." }).check(Schema.isInt()) })
