export const DoraOverview = Schema.Struct({ "deployment_frequency_series": Schema.Array(DeploymentFrequencyBucket).annotate({ "description": "Successful deployments per bucket across the window, oldest first, zero-filled, bucketed by series_granularity. Empty when the deploy tables aren't synced." }), "merge_to_deploy_series": Schema.Array(LeadTimeBucket).annotate({ "description": "Merge-to-deploy distribution per bucket across the window, oldest first: the box-plot series (min/p5/p25/p50/mean/p75/p95/max seconds per bucket). Empty when the deploy tables aren't synced, or when github_team was passed without membership data synced." }), "open_to_merge_series": Schema.Array(LeadTimeBucket).annotate({ "description": "Open-to-merge distribution over the SAME deployed PRs and buckets as merge_to_deploy_series, so the two stages compare bucket by bucket. Not the all-merged-PRs cycle time. Empty in the same cases as merge_to_deploy_series." }), "open_to_deploy_series": Schema.Array(LeadTimeBucket).annotate({ "description": "Open-to-deploy distribution over the same deployed PRs and buckets: the full open to first-successful-deploy span the two stages above compose into. Empty in the same cases as merge_to_deploy_series." }), "deploy_data_available": Schema.Boolean.annotate({ "description": "False when the deployments/deployment_statuses tables aren't synced for the selected repo; every other field is then empty or null, never a fake zero." }), "environment_scope": Schema.String.annotate({ "description": "Display label for the selected environments, comma-separated, 'persistent' when no persistent environments were discovered. Use selected_environments for exact names." }), "environments": Schema.Array(Schema.String).annotate({ "description": "Distinct persistent environments from the metric scan window or the 30 days before its end, whichever starts earlier, most-deployed first. Transient environments are omitted." }), "selected_environments": Schema.Array(Schema.String).annotate({ "description": "Exact environment names used for these metrics. Defaults to all persistent environments marked production or named prod/production (including regional suffixes), falling back to the busiest persistent environment. Explicit filters are trimmed and deduplicated. DRF rejects blank or unknown names; real transient names are allowed." }), "has_membership_data": Schema.Boolean.annotate({ "description": "True when the optional team-membership snapshot is synced. When false, a github_team filter cannot be honored and the merge-to-deploy figures go empty rather than silently unfiltered." }), "github_teams": Schema.Array(Schema.String).annotate({ "description": "Distinct GitHub team slugs from the membership snapshot, sorted: the team picker's options. Empty when membership isn't synced." }), "deployment_count": Schema.Number.annotate({ "description": "Deployments whose first success status landed in the window, within the environment scope." }).check(Schema.isInt()), "deployment_count_prev": Schema.Number.annotate({ "description": "Same count over the equal-length window before date_from." }).check(Schema.isInt()), "deployments_per_day": Schema.Never, "deployments_per_day_prev": Schema.Never, "median_merge_to_deploy_seconds": Schema.Never, "median_merge_to_deploy_seconds_prev": Schema.Never, "median_open_to_deploy_seconds": Schema.Never, "median_open_to_deploy_seconds_prev": Schema.Never, "deployed_pr_count": Schema.Number.annotate({ "description": "PRs first deployed in the window: the population behind the merge-to-deploy median and box plot." }).check(Schema.isInt()), "deployed_pr_count_prev": Schema.Number.annotate({ "description": "Previous-window twin of deployed_pr_count." }).check(Schema.isInt()), "failed_deployment_count": Schema.Number.annotate({ "description": "Deployments with at least one failure/error status, keyed on the first failure time." }).check(Schema.isInt()), "failed_deployment_count_prev": Schema.Number.annotate({ "description": "Previous-window twin of failed_deployment_count." }).check(Schema.isInt()), "failed_deployment_share": Schema.Never, "failed_deployment_share_prev": Schema.Never, "median_failed_deploy_to_next_success_seconds": Schema.Never, "median_failed_deploy_to_next_success_seconds_prev": Schema.Never, "merged_pr_count": Schema.Number.annotate({ "description": "PRs merged in the window (bots and drafts excluded; narrowed by github_team when given): the denominator behind unattributed_merged_pr_share." }).check(Schema.isInt()), "unattributed_merged_pr_share": Schema.Never, "latest_deploy_status_at": Schema.Union([Schema.String.annotate({ "description": "The newest deployment status row synced, any environment: how fresh the deploy data is. Windows ending after this instant undercount. Null when the deploy tables are empty.", "format": "date-time" })]), "series_granularity": Schema.String.annotate({ "description": "Bucket width of every series: the granularity param when given, else chosen to fit the window: 'hour', 'day', or 'week'." }) })
