export type NotebookRunStatusResponse = { readonly "run_id": string, readonly "status": string, readonly "trigger": string, readonly "variables": ReadonlyArray<NotebookVariable>, readonly "cell_count": number, readonly "current_index": number, readonly "current_node_id"?: string | null, readonly "failed_node_id"?: string | null, readonly "error"?: string | null, readonly "cells": ReadonlyArray<NotebookRunCell>, readonly "created_at": string, readonly "finished_at"?: string }
export const NotebookRunStatusResponse = Schema.Struct({ "run_id": Schema.String.annotate({ "description": "Identifier of the whole-notebook run.", "format": "uuid" }), "status": Schema.String.annotate({ "description": "Run state: 'running' (keep polling), or terminal — 'done', 'failed', or 'interrupted'." }), "trigger": Schema.String.annotate({ "description": "Which surface started the run: 'ui' or 'mcp'." }), "variables": Schema.Array(NotebookVariable).annotate({ "description": "The variable values this run bound, snapshotted when it started." }), "cell_count": Schema.Number.annotate({ "description": "How many cells the run executes." }).check(Schema.isInt()), "current_index": Schema.Number.annotate({ "description": "Position in the plan the run has reached, counting from 0." }).check(Schema.isInt()), "current_node_id": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "The cell the run is on; null once the plan is finished." })), "failed_node_id": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "The cell that stopped the run, when one did." })), "error": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Why the run stopped, in one sentence a person can read." })), "cells": Schema.Array(NotebookRunCell).annotate({ "description": "Every planned cell in run order, with the state of its run in this notebook run." }), "created_at": Schema.String.annotate({ "description": "When the run started.", "format": "date-time" }), "finished_at": Schema.optionalKey(Schema.Union([Schema.String.annotate({ "description": "When the run reached a terminal state; null while running.", "format": "date-time" })])) })
export type NotebookSQLV2RunRequest = { readonly "reuse_results"?: boolean, readonly "node_id": string, readonly "node_type"?: "hogql" | "python", readonly "code": string, readonly "output_name"?: string, readonly "refs"?: { readonly [x: string]: NotebookSQLV2Ref }, readonly "variables"?: ReadonlyArray<NotebookVariable>, readonly "connection_id"?: string, readonly "send_raw_query"?: boolean }
export const NotebookSQLV2RunRequest = Schema.Struct({ "reuse_results": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Reuse the requesting user's running or completed HogQL run with the same cell and resolved query from the last hour. Does not apply to token-only callers, kernel runs, or connection runs.", "default": false })), "node_id": Schema.String.annotate({ "description": "ProseMirror node id of the SQLV2 node being run." }), "node_type": Schema.optionalKey(Schema.Literals(["hogql", "python"]).annotate({ "description": "* `hogql` - hogql\n* `python` - python", "default": "hogql" })), "code": Schema.String.annotate({ "description": "The node's source — SQL for a hogql node, Python for a python node. Must not be blank." }), "output_name": Schema.optionalKey(Schema.String.annotate({ "description": "Kernel nodes only: the dataframe variable to bind the result to in the kernel namespace (a python node falls back to the last expression for its preview).", "default": "" })), "refs": Schema.optionalKey(Schema.Record(Schema.String, NotebookSQLV2Ref).annotate({ "description": "Available upstream nodes, keyed by dataframe name. A SQL node inlines referenced hogql refs as CTEs — unless it references a local ref, which reroutes the run to the sandbox's DuckDB; a python node materializes the hogql refs its code reads as pandas frames." })), "variables": Schema.optionalKey(Schema.Array(NotebookVariable).annotate({ "description": "Notebook-level variables in scope for this run. A SQL node has each `{name}` bound to its value before dispatch; a Python node gets them as globals in the kernel namespace. A SQL node reading a `{name}` that is absent here fails the dispatch." })), "connection_id": Schema.optionalKey(Schema.Union([Schema.String.annotate({ "description": "SQL nodes only: id of a direct-query-capable external data source to run against instead of PostHog's ClickHouse. Omit to query PostHog.", "format": "uuid" })])), "send_raw_query": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Send the code to the selected connection verbatim instead of compiling it from HogQL first. Ignored without connection_id, and incompatible with references to other cells.", "default": false })) })
