export const BillingAlertEvent = Schema.Struct({ "id": Schema.String.annotate({ "description": "Unique identifier for this billing alert event.", "readOnly": true, "format": "uuid" }), "kind": Schema.Literals(["check", "firing", "resolved", "errored", "broken_config"]).annotate({ "description": "* `check` - Check\n* `firing` - Firing\n* `resolved` - Resolved\n* `errored` - Errored\n* `broken_config` - Broken config", "readOnly": true }), "source": Schema.Literals(["scheduled", "manual"]).annotate({ "description": "* `scheduled` - Scheduled\n* `manual` - Manual", "readOnly": true }), "attempt_number": Schema.Number.annotate({ "description": "Attempt number for this billing date and configuration revision.", "readOnly": true }).check(Schema.isInt()), "created_at": Schema.String.annotate({ "description": "When this event was recorded.", "readOnly": true, "format": "date-time" }), "evaluation_date": Schema.Union([Schema.String.annotate({ "description": "Billing data date evaluated by this event.", "readOnly": true, "format": "date" })]), "configuration_revision": Schema.Number.annotate({ "description": "Configuration revision used for this evaluation.", "readOnly": true }).check(Schema.isInt()), "period_start": Schema.Union([Schema.String.annotate({ "description": "Start of the evaluated billing period.", "readOnly": true, "format": "date-time" })]), "period_end": Schema.Union([Schema.String.annotate({ "description": "End of the evaluated billing period.", "readOnly": true, "format": "date-time" })]), "metric": Schema.Literals(["spend", "projected_spend"]).annotate({ "description": "* `spend` - Spend\n* `projected_spend` - Projected spend", "readOnly": true }), "current_value": Schema.Union([Schema.String.check(Schema.isPattern(new RegExp("^-?\\d{0,14}(?:\\.\\d{0,6})?$"), { "description": "Metric value for the evaluated billing date.", "readOnly": true, "format": "decimal" }))]), "baseline_value": Schema.Union([Schema.String.check(Schema.isPattern(new RegExp("^-?\\d{0,14}(?:\\.\\d{0,6})?$"), { "description": "Average metric value across the baseline window.", "readOnly": true, "format": "decimal" }))]), "absolute_delta": Schema.Union([Schema.String.check(Schema.isPattern(new RegExp("^-?\\d{0,14}(?:\\.\\d{0,6})?$"), { "description": "Current value minus the baseline value.", "readOnly": true, "format": "decimal" }))]), "relative_delta_percentage": Schema.Union([Schema.String.check(Schema.isPattern(new RegExp("^-?\\d{0,22}(?:\\.\\d{0,6})?$"), { "description": "Percentage change against the baseline value.", "readOnly": true, "format": "decimal" }))]), "threshold_breached": Schema.Boolean.annotate({ "description": "Whether the evaluated value breached the configured threshold.", "readOnly": true }), "state_before": Schema.Union([BillingAlertConfigurationStateEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Alert state before this event was applied.\n\n* `not_firing` - Not firing\n* `firing` - Firing\n* `errored` - Errored\n* `snoozed` - Snoozed\n* `broken` - Broken", "readOnly": true }), "state_after": Schema.Union([BillingAlertConfigurationStateEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Alert state after this event was applied.\n\n* `not_firing` - Not firing\n* `firing` - Firing\n* `errored` - Errored\n* `snoozed` - Snoozed\n* `broken` - Broken", "readOnly": true }), "notification_sent_at": Schema.Union([Schema.String.annotate({ "description": "When notifications for this event were delivered.", "readOnly": true, "format": "date-time" })]), "targets_notified": Schema.Json.annotate({ "description": "Notification targets recorded for this event.", "readOnly": true }), "query_duration_ms": Schema.Union([Schema.Number.check(Schema.isInt()), Schema.Null]).annotate({ "description": "Milliseconds spent fetching billing data for this evaluation.", "readOnly": true }), "error_code": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Exception class name recorded when the evaluation failed.", "readOnly": true }), "error_message": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Failure description recorded when the evaluation failed.", "readOnly": true }), "reason": Schema.String.annotate({ "description": "Human-readable explanation of the evaluation outcome.", "readOnly": true }) })
