export const EndExperiment = Schema.Struct({ "conclusion": Schema.optionalKey(Schema.Union([ConclusionEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "The conclusion of the experiment.\n\n* `won` - won\n* `lost` - lost\n* `inconclusive` - inconclusive\n* `stopped_early` - stopped_early\n* `invalid` - invalid" })), "conclusion_comment": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxLength(4000, { "description": "Optional comment about the experiment conclusion." }))])), "open_cleanup_pr": Schema.optionalKey(Schema.Boolean.annotate({ "description": "When true, open a draft pull request that removes the experiment's feature-flag code from the linked repository. A personal API key needs the task:write scope (403 otherwise). Skipped when the conclusion is empty, or when no connected repository can be resolved.", "default": false })), "repository": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxLength(255, { "description": "GitHub repository to open the cleanup pull request in, in `organization/repository` format. Only used when open_cleanup_pr is true. It must be one of the team's connected repositories (see the flag_cleanup_target action); it is then saved as the experiment's repository. When omitted, the experiment's saved repository, the team's default cleanup repository, or the team's only connected repository is used." }))])), "set_repository_as_team_default": Schema.optionalKey(Schema.Boolean.annotate({ "description": "When true, also save `repository` as this environment's default cleanup repository, used for experiments that have no repository of their own. Only acts when open_cleanup_pr is true and `repository` is provided and belongs to the team's GitHub installation. Requires project admin access (403 otherwise).", "default": false })) })
export type ExperimentWatchCard = { readonly "kind": "behavior" | "friction" | "variant_only" | "metric", readonly "event": string, readonly "variant": string, readonly "strength": ExperimentWatchCardStrengthEnum | NullEnum, readonly "metric_name": string | null, readonly "recording_count": number, readonly "session_ids": ReadonlyArray<string>, readonly "highlights": ReadonlyArray<ExperimentWatchHighlight> }
export const ExperimentWatchCard = Schema.Struct({ "kind": Schema.Literals(["behavior", "friction", "variant_only", "metric"]).annotate({ "description": "* `behavior` - behavior\n* `friction` - friction\n* `variant_only` - variant_only\n* `metric` - metric" }), "event": Schema.String.annotate({ "description": "The event behind the card." }), "variant": Schema.String.annotate({ "description": "The variant whose recordings these are: for comparison cards, the one that did the event more." }), "strength": Schema.Union([ExperimentWatchCardStrengthEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "How far apart this variant and the rest are, as a band rather than a number: 'only' when nobody in the other variants did it at all among the people compared, then 'far_more', 'more' and 'slightly_more'. Read off the conservative end of the difference, so a card that clears the bar only because the sample is large reports as slight. Null on metric cards, which compare nothing. Present a band as a comparison ('far more common in test'), never convert it into a multiple.\n\n* `only` - only\n* `far_more` - far_more\n* `more` - more\n* `slightly_more` - slightly_more" }), "metric_name": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "The metric this card's event belongs to, on a comparison card as well as on a shortcut card. When set, the experiment's results measure this event over the whole run window with the statistics that go with a result, so say the card points there and never present the card as a second answer about that metric. Null when no metric counts the event." }), "recording_count": Schema.Number.annotate({ "description": "How many recordings the card carries, at most max_card_recordings (20). Every card is backed by recordings that actually exist: a finding whose sessions were never recorded is dropped rather than promised. A count sitting on the ceiling means at least that many, so say 'at least' and never compare two such counts: how often the event happened is the experiment's results, and this only counts what replay kept." }).check(Schema.isInt()), "session_ids": Schema.Array(Schema.String).annotate({ "description": "The recordings themselves, most recent first, ready to hand to the recordings list as-is." }), "highlights": Schema.Array(ExperimentWatchHighlight).annotate({ "description": "Which of the card's recordings to open first, at most 3, ranked by how much each one carries: recordings showing several kinds of signal at once come before recordings showing more of a single kind. Offer these before the full list: the recordings list orders by its own sort, so session_ids order never reaches the viewer, and twenty recordings that share an event are otherwise indistinguishable in it. Empty when no recording the viewer can open carries a signal, which is worth saying rather than hiding." }) }).annotate({ "description": "One group of recordings worth opening, and the sentence that justifies it.\n\nDeliberately no rate, no ratio and no person count: a precise number next to an event name is\nan effect size, and the experiment's results publish those for everything it measures, computed\nover a different window and a different unit. The only number here is how many recordings the\ncard can actually show." })
