export const ResolvedToolPolicy = Schema.Struct({ "tool_name": Schema.String.annotate({ "description": "Tool name as exposed by the upstream server." }), "description": Schema.String.annotate({ "description": "Tool description from the upstream server." }), "input_schema": Schema.Record(Schema.String, Schema.Json).annotate({ "description": "JSON Schema describing the tool's input arguments." }), "is_destructive": Schema.Boolean.annotate({ "description": "Whether the canonical gateway heuristic treats this tool as destructive." }), "policy_state": Schema.Literals(["approved", "needs_approval", "do_not_use"]).annotate({ "description": "* `approved` - Approved\n* `needs_approval` - Needs approval\n* `do_not_use` - Do not use" }), "team_state": Schema.Union([MCPToolApprovalStateEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "What the team-level chain (row or preset) yields, ignoring the scope. Null when the team imposes nothing.\n\n* `approved` - Approved\n* `needs_approval` - Needs approval\n* `do_not_use` - Do not use" }), "locked": Schema.Boolean.annotate({ "description": "True when no state is editable for this scope (a rule match or a Blocked team ceiling)." }), "decided_by": Schema.Literals(["rule", "scope", "team", "preset", "legacy", "default"]).annotate({ "description": "* `rule` - rule\n* `scope` - scope\n* `team` - team\n* `preset` - preset\n* `legacy` - legacy\n* `default` - default" }), "rule_name": Schema.String.annotate({ "description": "Matching org rule name, when decided_by is rule." }), "rule_description": Schema.String.annotate({ "description": "Matching org rule description, when decided_by is rule." }) }).annotate({ "description": "One tool with its effective policy for the requested scope." })
export type S3CompatibleDestinationConfig = { readonly "bucket_name": string, readonly "region": string, readonly "prefix": string, readonly "compression"?: CompressionEnum | NullEnum, readonly "file_format"?: "Parquet" | "JSONLines", readonly "max_file_size_mb"?: number | null, readonly "legacy_parquet_extension"?: boolean, readonly "use_virtual_style_addressing"?: boolean }
export const S3CompatibleDestinationConfig = Schema.Struct({ "bucket_name": Schema.String.annotate({ "description": "Name of the destination bucket." }), "region": Schema.String.annotate({ "description": "Region the bucket is in (e.g. 'us-east-1')." }), "prefix": Schema.String.annotate({ "description": "Object key prefix applied to every exported file." }), "compression": Schema.optionalKey(Schema.Union([CompressionEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Optional compression codec applied to exported files. Valid codecs depend on file_format.\n\n* `brotli` - brotli\n* `gzip` - gzip\n* `lz4` - lz4\n* `snappy` - snappy\n* `zstd` - zstd" })), "file_format": Schema.optionalKey(Schema.Literals(["Parquet", "JSONLines"]).annotate({ "description": "* `Parquet` - Parquet\n* `JSONLines` - JSONLines", "default": "JSONLines" })), "max_file_size_mb": Schema.optionalKey(Schema.Union([Schema.Number.check(Schema.isInt()), Schema.Null]).annotate({ "description": "If set, rolls to a new file once the current file exceeds this size in MB." })), "legacy_parquet_extension": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Whether Parquet files keep the compression codec in their extension, for example '.parquet.zst' rather than '.parquet'. Parquet records its codec inside the file, so new exports leave it out. An export that already wrote Parquet files before this setting existed keeps it, so that pipelines matching on the old names do not break. Has no effect on JSON Lines, which always carries the codec in its extension." })), "use_virtual_style_addressing": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Use virtual-hosted-style addressing rather than path-style.", "default": false })) }).annotate({ "description": "Typed configuration for an S3-compatible batch-export destination (Cloudflare R2,\nDigitalOcean Spaces, etc.).\n\nCredentials and the provider `endpoint_url` live in the linked s3-compatible Integration.\nMirrors the non-credential fields of `S3CompatibleBatchExportInputs` in\n`products/batch_exports/backend/service.py`." })
