export const QuarantineRequest = Schema.Struct({ "operation": Schema.Literals(["quarantine", "extend", "remove"]).annotate({ "description": "* `quarantine` - QUARANTINE\n* `extend` - EXTEND\n* `remove` - REMOVE" }), "selector": Schema.String.annotate({ "description": "Test selector to act on: an exact test id, a file, a directory, a class prefix, or 'product:<dashed-name>'." }), "runner": Schema.optionalKey(Schema.Union([QuarantineRequestRunnerEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Test runner the selector targets: 'pytest', 'jest', or 'playwright'. Existing entries and Jest file extensions are inferred for older clients that omit it; other selectors default to 'pytest'.\n\n* `pytest` - PYTEST\n* `jest` - JEST\n* `playwright` - PLAYWRIGHT" })), "repo": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Optional 'owner/name' repository override; defaults to the team's most active repo." })), "reason": Schema.optionalKey(Schema.String.annotate({ "description": "Why the test is quarantined. Required for quarantine and extend; ignored by remove." })), "owner": Schema.optionalKey(Schema.String.annotate({ "description": "GitHub team or user handle responsible for the fix, e.g. '@PostHog/team-x'. Required for quarantine and extend." })), "issue": Schema.optionalKey(Schema.String.annotate({ "description": "Existing tracking issue URL, carried forward on extend and remove. Ignored by quarantine, which files a fresh issue." })), "expires": Schema.optionalKey(Schema.Union([Schema.String.annotate({ "description": "ISO date the quarantine expires (at most 30 days out). Defaults to 14 days from today. Ignored by remove.", "format": "date" })])), "mode": Schema.optionalKey(Schema.Literals(["run", "skip"]).annotate({ "description": "* `run` - RUN\n* `skip` - SKIP" })) })
