export const QuarantineFile = Schema.Struct({ "entries": Schema.Array(QuarantineEntry).annotate({ "description": "Quarantined selectors, most urgent first (overdue, in_grace, expiring_soon, active), then by soonest expiry." }), "repo": Schema.Union([RepoRef, Schema.Null], { mode: "oneOf" }).annotate({ "description": "Repository the file was read from. Null in local-dev mode, where the server's own checkout is read." }), "available": Schema.Boolean.annotate({ "description": "False when the repository has no quarantine file (not an error) or it could not be fetched." }), "parse_errors": Schema.Array(Schema.String).annotate({ "description": "Contract violations (malformed JSON, bad entries) or fetch failures. Malformed entries are dropped; well-formed ones are kept." }), "parse_warnings": Schema.Array(Schema.String).annotate({ "description": "Forward-compatibility notices, e.g. unknown entry fields." }), "source_url": Schema.String.annotate({ "description": "GitHub blob URL of the quarantine file, or empty when read locally or unavailable." }), "generated_at": Schema.String.annotate({ "description": "When this snapshot was computed (UTC); expiry math uses this clock.", "format": "date-time" }) })
