export const ReportMetricWrite = Schema.Struct({ "metric_id": Schema.String.annotate({ "description": "Stable slug for this metric within the report: lowercase letters, numbers, underscores, and hyphens, starting with a letter or number." }).check(Schema.isMaxLength(100)), "title": Schema.String.annotate({ "description": "Short human-readable label for the measurement." }).check(Schema.isMaxLength(200)), "kind": Schema.Literals(["affected_users", "affected_sessions", "occurrences", "conversion_rate", "error_rate", "duration", "revenue", "custom"]).annotate({ "description": "* `affected_users` - affected_users\n* `affected_sessions` - affected_sessions\n* `occurrences` - occurrences\n* `conversion_rate` - conversion_rate\n* `error_rate` - error_rate\n* `duration` - duration\n* `revenue` - revenue\n* `custom` - custom" }), "role": Schema.optionalKey(Schema.Literals(["primary", "supporting"]).annotate({ "description": "* `primary` - primary\n* `supporting` - supporting", "default": "supporting" })), "value": Schema.optionalKey(Schema.Never), "value_at": Schema.optionalKey(Schema.Union([Schema.String.annotate({ "description": "When the visible snapshot value was measured; null when value is null.", "format": "date-time" })])), "series": Schema.optionalKey(Schema.Union([Schema.Array(Schema.Number.annotate({ "format": "double" }).check(Schema.isFinite())).check(Schema.isMaxLength(14, { "description": "Trailing per-bucket values of the live query, oldest first, saved with the value snapshot so a list row can draw the trend without running the query; at most 14 points. Null when no snapshot series is available to this viewer." }))])), "value_format": Schema.optionalKey(Schema.Literals(["number", "count", "percentage", "percentage_scaled", "duration", "currency"]).annotate({ "description": "* `number` - number\n* `count` - count\n* `percentage` - percentage\n* `percentage_scaled` - percentage_scaled\n* `duration` - duration\n* `currency` - currency", "default": "number" })), "unit": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxLength(40, { "description": "Optional short suffix or currency code, such as `users`, `ms`, or `USD`." }))])), "query": Schema.Json.annotate({ "description": "Required when authoring: a live InsightVizNode wrapping one bounded TrendsQuery. Consumers derive a BoldNumber execution for the whole-window aggregate and an ActionsBar execution for longitudinal buckets. The query must produce exactly one output series and no more than 1000 estimated longitudinal points; one formula may combine up to ten event or action source series. An affected_users metric uses exactly one source with `math: dau`; never sum its per-bucket unique-user values. A response omits this on list or redacts it to null on detail when the viewer lacks access to the definition." }), "caption": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxLength(500, { "description": "Optional context the tile cannot show, such as a filter that narrows the count or a caveat on the data. Omit it rather than restate the title, unit, or window." }))])), "comparison": Schema.optionalKey(Schema.Union([ReportMetricComparison, Schema.Null], { mode: "oneOf" }).annotate({ "description": "Legacy optional comparison. New report metrics must omit it." })) }).annotate({ "description": "Authoring shape: unlike a read response, the live query cannot be absent or redacted." })
