export const PatchedSignalScoutConfigUpdate = Schema.Struct({ "display_name": Schema.optionalKey(Schema.String.annotate({ "description": "Name shown wherever people identify this scout, written however you want it — spaces, capitalization, and acronyms are kept as typed, and two scouts may share one. It does not change the scout's skill name, which stays its identity, so renaming a scout keeps its schedule, run history, notes, memory, and links. At most 200 characters; blank means the scout has no name of its own and is labelled from its skill name instead." }).check(Schema.isMaxLength(200))), "enabled": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Whether this scout runs on its schedule. Disabled scouts are skipped by the coordinator. Turning this off records a user pause (`status` becomes `paused_by_user`, which the system never overrides); turning it on resumes the scout from any pause. Only a change of value is a lifecycle action: re-sending the current value leaves the existing status and its ownership untouched." })), "emit": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Whether the scout writes findings to the inbox. False = dry-run: it runs and logs but emits nothing." })), "run_interval_minutes": Schema.optionalKey(Schema.Number.annotate({ "description": "Minutes between runs (30–43200). Use 1440 for a daily schedule." }).check(Schema.isInt()).check(Schema.isGreaterThanOrEqualTo(30)).check(Schema.isLessThanOrEqualTo(43200))), "run_cron_schedule": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxLength(100, { "description": "Optional five-field cron expression, e.g. '30 9 * * *' (daily at 09:30), '0 9,17 * * *' (twice daily), or '0 9 * * 1-5' (weekday mornings). Evaluated in the project timezone. Takes precedence over `run_interval_minutes`; occurrences must be at least 30 minutes apart. Set null to return to the rolling interval schedule." }))])), "output_destinations": Schema.optionalKey(Schema.Struct({ "slack": Schema.optionalKey(Schema.Union([SignalScoutSlackDestinationUpdate, Schema.Null], { mode: "oneOf" }).annotate({ "description": "Slack destination for each emitted scout finding or report. Null or omitted disables Slack delivery." })), "webhook": Schema.optionalKey(Schema.Union([SignalScoutWebhookDestination, Schema.Null], { mode: "oneOf" }).annotate({ "description": "The CDP destination another product provisioned for this scout's reports. Null or omitted means no webhook. Unlike Slack, Signals does not deliver this itself: the reference lives here so the owning product can manage the destination's lifecycle." })) }).annotate({ "description": "Destinations that receive each finding or report this scout emits. Pass an empty object to disable delivery." })), "structured_output_schema": Schema.optionalKey(Schema.Union([Schema.Struct({  }).annotate({ "description": "Optional JSON Schema (draft 2020-12) describing ONE structured record this scout produces via `scout-record-output` — e.g. a per-report quality judgment (`{\"type\": \"object\", \"properties\": {\"verdict\": {\"enum\": [\"good\", \"bad\", \"unsure\"]}, \"reason\": {\"type\": \"string\"}}, \"required\": [\"verdict\", \"reason\"]}`). The root must be `\"type\": \"object\"`. Setting a schema turns the structured-output channel on: the run prompt renders the schema and every submitted record is validated against it and recorded in the project as a `$scout_structured_output` event, queryable like any event. The channel also requires emit — a dry-run scout has nowhere to record to. Cardinality is the scout's call (one record per run, one per judged entity, ...). Null = channel off. Setting a schema requires skill-authoring authorization (the `llm_skill:write` scope and skill editor access) since the scout reads it verbatim in its prompt; clearing it needs only the config write. Records validate against the schema in force when the run was dispatched." })])), "network_access": Schema.optionalKey(Schema.Literals(["trusted", "full"]).annotate({ "description": "* `trusted` - Trusted domains only\n* `full` - Full" })), "model": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxLength(200, { "description": "Optional model id this scout's runs are pinned to, e.g. `claude-opus-4-5`. Must be one of the platform's agent models; an invalid id is rejected with the available ones listed. Null keeps the default model, chosen by the platform. Early access: the pin can only be set on projects enrolled in the scout model preview, and only takes effect there. Set null to clear it." }))])), "auto_pause_exempt": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Exempt this scout from the inactivity sweep, meaning both the `ignored` pause and the `no_output` quiet warning. Set it on watchdog scouts whose value is staying quiet." })), "tags": Schema.optionalKey(Schema.Array(Schema.String).annotate({ "description": "Free-form labels for grouping the fleet, e.g. `[\"revenue\", \"on-call\"]`. Normalized to lowercase kebab-case (`On Call` and `on_call` both become `on-call`), deduped, and stored sorted; at most 10 tags, each at most 50 characters once normalized. Pass the full desired set — a write replaces the existing tags rather than merging into them. Filter the config list with the `tags` query parameter." }).check(Schema.isMaxLength(10))), "mcp_gateway_server_ids": Schema.optionalKey(Schema.Array(Schema.String.annotate({ "format": "uuid" })).annotate({ "description": "MCP gateway servers (by id) this scout's runs may use, chosen from the connections members shared to the whole team. Selection is per scout: an empty list gives the scout no MCP servers. Applies from the scout's next run." }).check(Schema.isMaxLength(100))), "repositories": Schema.optionalKey(Schema.Array(Schema.String.check(Schema.isMaxLength(255))).annotate({ "description": "GitHub repositories this scout clones into its sandbox, each in `organization/repo` format. Set them for a scout that reads code, so it can search the tree and run the project's own tests instead of reading files one API call at a time. Empty (the default) leaves the sandbox without a checkout. The scout's GitHub access stays read-only either way, so a repository listed here is never writable from a run. At most 10, each reachable through the project's GitHub connection. Applies from the scout's next run." }).check(Schema.isMaxLength(10))), "write_scopes": Schema.optionalKey(Schema.Array(Schema.String).annotate({ "description": "Extra write access granted to this one scout, as scope strings. The grantable set is `alert:write`, `annotation:write`, `dashboard:write`, `insight:write`, `llm_skill:write`, `replay_scanner:write`, `warehouse_table:write`, `warehouse_view:write`. Empty (the default) means the scout reads the project and writes only what every scout may write: notebooks, its findings, and its own memory. Each scope is project-wide and object-level, so a scout holding `dashboard:write` can update or delete any dashboard in the project, not only ones it made. Grant only what this scout maintains. Only the person the scout's runs act as (whoever authored it) or a project admin can set it, and a scoped API key must itself carry each scope it grants. A dry run (`emit=false`) never holds the grant. Applies from the scout's next run." }).check(Schema.isMaxLength(8))) }).annotate({ "description": "Editable display name, schedule, enablement, and emit posture for one scout config." })
