export type PatchedSignalSourceConfig = { readonly "id"?: string, readonly "source_product"?: SignalSourceProductEnum, readonly "source_type"?: SignalSourceConfigSourceTypeEnum, readonly "enabled"?: boolean, readonly "config"?: { readonly [x: string]: Schema.Json }, readonly "created_at"?: string, readonly "updated_at"?: string, readonly "status"?: SignalSourceSyncStatusEnum | NullEnum }
export const PatchedSignalSourceConfig = Schema.Struct({ "id": Schema.optionalKey(Schema.String.annotate({ "readOnly": true, "format": "uuid" })), "source_product": Schema.optionalKey(SignalSourceProductEnum), "source_type": Schema.optionalKey(SignalSourceConfigSourceTypeEnum), "enabled": Schema.optionalKey(Schema.Boolean), "config": Schema.optionalKey(Schema.Record(Schema.String, Schema.Json).annotate({ "description": "Per-source settings as a JSON object. Keys read by the emission actionability gate on sources that define one (most data warehouse imports, and Conversations): `steering` (string, max 2000 characters) holds the team's preferences about this source's records in plain language: what matters, what to skip, what's out of scope. The emission actionability gate applies it when deciding which records become signals; rules apply from the next sync and nothing already emitted is retracted. `default_not_actionable` (boolean, default false) flips the gate's default: instead of keeping every record the steering rules don't exclude, only records that clearly match the team's preferences are kept. Other sources store these keys without reading them yet; future pipeline stages will consume the same steering text. Some sources read additional keys, for example `recording_filters` and `sample_rate` for session analysis. The Linear issue source (`source_product=linear`, `source_type=issue`) reads `linear_team_ids` (list of Linear team id strings, max 100): the warehouse still syncs the whole Linear workspace, but only issues from those teams become signals. Omit the key or pass an empty list to use every team. Get the ids from the Linear integration's teams endpoint." })), "created_at": Schema.optionalKey(Schema.String.annotate({ "readOnly": true, "format": "date-time" })), "updated_at": Schema.optionalKey(Schema.String.annotate({ "readOnly": true, "format": "date-time" })), "status": Schema.optionalKey(Schema.Union([SignalSourceSyncStatusEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Sync state of the warehouse import behind this source: `running`, `failed`, or `completed`. Null for a source that imports nothing from the warehouse, for an import that has never synced, and when the sync state could not be read.", "readOnly": true })) })
