export const ReportChart = Schema.Struct({ "chart_id": Schema.String.annotate({ "description": "Stable slug for this chart within the report (lowercase letters, numbers, underscores, hyphens; must start with a letter or number). Reference it from `summary` as a markdown link with a `chart:` target — `[Daily signups](chart:signups-drop)` — to place the chart at that point in the body. A chart you don't reference still renders, below the summary." }).check(Schema.isMaxLength(100)), "title": Schema.String.annotate({ "description": "Short heading shown above the chart." }).check(Schema.isMaxLength(200)), "query": Schema.Json.annotate({ "description": "The query node to render. `kind` must be `InsightVizNode` (an ad-hoc product analytics chart), `DataVisualizationNode` (a SQL series — a `HogQLQuery` source plus a `display`), or `SavedInsightNode` (an existing insight by `shortId`). Pin the window to absolute dates where the node supports it, so the reader sees the data you wrote about rather than whatever a relative range resolves to when they open the report." }), "caption": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxLength(500, { "description": "Optional one-line note on what to look at in the chart." }))])), "size": Schema.optionalKey(Schema.Union([SizeEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "How much height the chart gets: `small` for a single number or a short series, `medium` for an ordinary graph, `large` when there are rows or a grid to read (retention, paths, a wide breakdown). Leave it out unless the default looks wrong — the inbox sizes a chart from its query, and two charts referenced from the same paragraph sit side by side.\n\n* `small` - small\n* `medium` - medium\n* `large` - large" })) }).annotate({ "description": "One chart attached to a report — rendered in the inbox and referenceable from the summary." })
