export const EditReportRequest = Schema.Struct({ "report_id": Schema.String.annotate({ "description": "Id of the report to edit (must belong to this project)." }), "title": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxLength(300, { "description": "Optional new title. Conventional-commit style (`type(scope): description`) renders with type/scope styling. The pipeline may later re-research and overwrite it." }))])), "summary": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxLength(20000, { "description": "Optional new summary. Markdown is supported (headings, lists, code, links; images are not rendered); lead with one plain declarative sentence — it becomes the inbox card headline. A heading, or a bold label on a line of its own with a blank line above it, marks a section that a threaded Slack delivery splits into its own reply. The pipeline may later re-research and overwrite it." }))])), "append_note": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxLength(10000, { "description": "Optional free-form note to append to the report's work log (attributed to this scout)." }))])), "corroboration_only": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Set only when append_note confirms the finding with no new information. After four confirmations, store only the count. Other notes remain in the work log." })), "append_evidence": Schema.optionalKey(Schema.Union([Schema.Array(Schema.Struct({ "description": Schema.String.annotate({ "description": "Prose for this observation. Embedded and rendered to the safety/research surfaces." }).check(Schema.isMaxLength(4000)), "source_id": Schema.String.annotate({ "description": "Stable id for this observation within the report (lets a later edit address it)." }) }).annotate({ "description": "One observation backing an authored report — becomes a bound signal row on the report." })).check(Schema.isMaxLength(50, { "description": "Optional observations to add to the report's evidence rail, each becoming a bound signal attributed to this scout — adds to the report's evidence rather than replacing it. Use this for a new observation a reader should be able to check, and `append_note` for commentary (the owning team knows, a deploy fixed it). The report's signal count and weight move with the appended rows. Emit plus every append share a cap of 50 signals per report." }))])), "suggested_reviewers": Schema.optionalKey(Schema.Array(SuggestedReviewer).annotate({ "description": "Optional reviewers to set on the report (each a `github_login` and/or `user_uuid`), replacing any existing list. Use this to route a report that surfaced with no reviewer — it re-runs autostart, so a report that was missing a qualifying reviewer can now open a draft PR. An empty list is a no-op (existing reviewers are left untouched, never cleared)." }).check(Schema.isMaxLength(10))), "repository": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Optional repository to point the report at, as `owner/repo` — the fix for a report that surfaced against the wrong codebase, so you correct it in place instead of filing a duplicate. It replaces the report's current target and re-runs autostart, so a report that had no repository to open a PR against can now open a draft PR. Omit the field to leave the target as it is, and pass the `NO_REPO` sentinel for a report where nothing under version control could change." })), "charts": Schema.optionalKey(Schema.Union([Schema.Array(Schema.Struct({ "chart_id": Schema.String.annotate({ "description": "Stable slug for this chart within the report (lowercase letters, numbers, underscores, hyphens; must start with a letter or number). Reference it from `summary` as a markdown link with a `chart:` target — `[Daily signups](chart:signups-drop)` — to place the chart at that point in the body. A chart you don't reference still renders, below the summary." }).check(Schema.isMaxLength(100)), "title": Schema.String.annotate({ "description": "Short heading shown above the chart." }).check(Schema.isMaxLength(200)), "query": Schema.Json.annotate({ "description": "The query node to render. `kind` must be `InsightVizNode` (an ad-hoc product analytics chart), `DataVisualizationNode` (a SQL series — a `HogQLQuery` source plus a `display`), or `SavedInsightNode` (an existing insight by `shortId`). Pin the window to absolute dates where the node supports it, so the reader sees the data you wrote about rather than whatever a relative range resolves to when they open the report." }), "caption": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxLength(500, { "description": "Optional one-line note on what to look at in the chart." }))])), "size": Schema.optionalKey(Schema.Union([SizeEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "How much height the chart gets: `small` for a single number or a short series, `medium` for an ordinary graph, `large` when there are rows or a grid to read (retention, paths, a wide breakdown). Leave it out unless the default looks wrong — the inbox sizes a chart from its query, and two charts referenced from the same paragraph sit side by side.\n\n* `small` - small\n* `medium` - medium\n* `large` - large" })) }).annotate({ "description": "One chart attached to a report — rendered in the inbox and referenceable from the summary." })).check(Schema.isMaxLength(20, { "description": "The full set of charts the report should show. Replaces the report's charts rather than adding to them, the way `summary` replaces the summary — so send every chart you want kept. Omit the field (or send null) to leave the report's existing charts untouched, and send an empty list to take them all down." }))])), "metrics": Schema.optionalKey(Schema.Union([Schema.Array(Schema.Struct({ "metric_id": Schema.String.annotate({ "description": "Stable slug for this metric within the report: lowercase letters, numbers, underscores, and hyphens, starting with a letter or number." }).check(Schema.isMaxLength(100)), "title": Schema.String.annotate({ "description": "Short human-readable label for the measurement." }).check(Schema.isMaxLength(200)), "kind": Schema.Literals(["affected_users", "affected_sessions", "occurrences", "conversion_rate", "error_rate", "duration", "revenue", "custom"]).annotate({ "description": "* `affected_users` - affected_users\n* `affected_sessions` - affected_sessions\n* `occurrences` - occurrences\n* `conversion_rate` - conversion_rate\n* `error_rate` - error_rate\n* `duration` - duration\n* `revenue` - revenue\n* `custom` - custom" }), "role": Schema.optionalKey(Schema.Literals(["primary", "supporting"]).annotate({ "description": "* `primary` - primary\n* `supporting` - supporting", "default": "supporting" })), "value": Schema.optionalKey(Schema.Never), "value_at": Schema.optionalKey(Schema.Union([Schema.String.annotate({ "description": "When the visible snapshot value was measured; null when value is null.", "format": "date-time" })])), "series": Schema.optionalKey(Schema.Union([Schema.Array(Schema.Number.annotate({ "format": "double" }).check(Schema.isFinite())).check(Schema.isMaxLength(14, { "description": "Trailing per-bucket values of the live query, oldest first, saved with the value snapshot so a list row can draw the trend without running the query; at most 14 points. Null when no snapshot series is available to this viewer." }))])), "value_format": Schema.optionalKey(Schema.Literals(["number", "count", "percentage", "percentage_scaled", "duration", "currency"]).annotate({ "description": "* `number` - number\n* `count` - count\n* `percentage` - percentage\n* `percentage_scaled` - percentage_scaled\n* `duration` - duration\n* `currency` - currency", "default": "number" })), "unit": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxLength(40, { "description": "Optional short suffix or currency code, such as `users`, `ms`, or `USD`." }))])), "query": Schema.Json.annotate({ "description": "Required when authoring: a live InsightVizNode wrapping one bounded TrendsQuery. Consumers derive a BoldNumber execution for the whole-window aggregate and an ActionsBar execution for longitudinal buckets. The query must produce exactly one output series and no more than 1000 estimated longitudinal points; one formula may combine up to ten event or action source series. An affected_users metric uses exactly one source with `math: dau`; never sum its per-bucket unique-user values. A response omits this on list or redacts it to null on detail when the viewer lacks access to the definition." }), "caption": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxLength(500, { "description": "Optional context the tile cannot show, such as a filter that narrows the count or a caveat on the data. Omit it rather than restate the title, unit, or window." }))])), "comparison": Schema.optionalKey(Schema.Union([ReportMetricComparison, Schema.Null], { mode: "oneOf" }).annotate({ "description": "Legacy optional comparison. New report metrics must omit it." })) }).annotate({ "description": "Authoring shape: unlike a read response, the live query cannot be absent or redacted." })).check(Schema.isMaxLength(6, { "description": "The report's full impact-metric set. Omit or send null to preserve it; send an empty list to clear it. Every metric requires a bounded live InsightVizNode/TrendsQuery built only from EventsNode or ActionsNode sources and capped at 1,000 estimated longitudinal points. Consumers derive BoldNumber and ActionsBar shapes; a snapshot is only an optional cached fallback. Snapshot-only/queryless payloads are invalid, and legacy rows of that shape are always redacted." }))])), "suggested_prompts": Schema.optionalKey(Schema.Union([Schema.Array(Schema.String.check(Schema.isMaxLength(200))).check(Schema.isMaxLength(3, { "description": "The full set of follow-up prompts (questions or next-step actions) the report should offer above its `Ask AI` box. Replaces the report's prompts rather than adding to them, so send every one you want kept. Omit the field (or send null) to leave them untouched, and send an empty list to take them down, which is what you want once a rewrite has left them pointing at the old report." }))])), "links": Schema.optionalKey(Schema.Array(ReportLinkWrite).annotate({ "description": "Typed, directed links from this report to others, recording how the work relates. Use `depends_on` when you split one finding into a stack and the second report's fix cannot land until the first one's does, so the order is recorded rather than left to a reader of the diffs. Additive: links join what the report already has rather than replacing them, and only this report gets a row, so link from the side the sentence starts at. Links of the same kind must stay acyclic and every report must be in this project." }).check(Schema.isMaxLength(10))), "supersedes_implementation": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Set this only when your rewrite changes what the fix should be: a different root cause, a different file or layer, a materially wider or narrower scope. More evidence for the same fix is not a reason, because the report's open pull request already implements it. Setting it true records a replacement decision for a ready report. Policy and eligibility checks gate the replacement. The existing pull request closes only after a successful, verified replacement. Technical failures retry automatically; policy blocks wait for a new edit or research trigger. Only honored alongside a `title` or `summary` that actually changes, and only within the first four content revisions, including revisions that did not request replacement." })) }).annotate({ "description": "Request body for `edit-report`. Can target ANY of the team's inbox reports, not just scout-authored ones." })
