export const CustomPropertySyncRun = Schema.Struct({ "id": Schema.String.annotate({ "readOnly": true, "format": "uuid" }), "job_id": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Warehouse import or materialization job associated with the run, if any.", "readOnly": true }), "account_segment": Schema.Union([SyncSegmentEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Account segment processed by this run. Person and group property runs return null.\n\n* `tracked` - tracked\n* `ignored` - ignored", "readOnly": true }), "sync_phase": Schema.Union([SyncPhaseEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Current account sync phase. Person and group property runs return null.\n\n* `staging` - staging\n* `dispatching` - dispatching\n* `syncing` - syncing\n* `completed` - completed", "readOnly": true }), "attempt": Schema.Union([Schema.Number.check(Schema.isInt()), Schema.Null]).annotate({ "description": "Latest Temporal activity attempt for the current account sync phase.", "readOnly": true }), "workflow_id": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Temporal workflow identifier associated with the current account sync phase.", "readOnly": true }), "workflow_run_id": Schema.Union([Schema.String.annotate({ "description": "Temporal run identifier associated with the current account sync phase.", "readOnly": true, "format": "uuid" })]), "temporal_url": Schema.Union([Schema.String.annotate({ "description": "Staff-only link to this run in Temporal. Null for non-staff users and runs without a Temporal ID.", "readOnly": true, "format": "uri" })]), "trigger": Schema.String.annotate({ "description": "What started the run: 'scheduled' (rode a warehouse sync), 'sync' (a warehouse sync started from the UI), 'manual' (a backfill started from the UI), or 'backfill' (the automatic backfill run when a mapping is created or re-enabled).", "readOnly": true }), "status": Schema.String.annotate({ "description": "Run status: 'running', 'completed', or 'failed'.", "readOnly": true }), "started_at": Schema.Union([Schema.String.annotate({ "description": "When the run began.", "readOnly": true, "format": "date-time" })]), "finished_at": Schema.Union([Schema.String.annotate({ "description": "When the run ended, or null while running.", "readOnly": true, "format": "date-time" })]), "rows_read": Schema.Number.annotate({ "description": "Warehouse rows scanned this run.", "readOnly": true }).check(Schema.isInt()), "changed": Schema.Number.annotate({ "description": "Rows whose mapped values changed since the last run.", "readOnly": true }).check(Schema.isInt()), "existing": Schema.Number.annotate({ "description": "Changed rows that matched an existing account, person, or group.", "readOnly": true }).check(Schema.isInt()), "produced": Schema.Number.annotate({ "description": "Property updates written or produced to the ingestion pipeline.", "readOnly": true }).check(Schema.isInt()), "skipped_missing_person": Schema.Number.annotate({ "description": "Changed rows skipped because no existing account, person, or group matched the key column value.", "readOnly": true }).check(Schema.isInt()), "error": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Error summary if the run failed, else null.", "readOnly": true }), "created_at": Schema.String.annotate({ "description": "When the run row was recorded.", "readOnly": true, "format": "date-time" }) }).annotate({ "description": "One warehouse-backed custom property sync run." })
