export type WarmTaskRequest = { readonly "repository"?: string, readonly "repositories"?: ReadonlyArray<string>, readonly "github_integration"?: number | null, readonly "branch"?: string, readonly "runtime_adapter"?: RuntimeAdapterEnum | NullEnum, readonly "model"?: string | null, readonly "reasoning_effort"?: ReasoningEffortEnum | NullEnum, readonly "sandbox_environment_id"?: string, readonly "custom_image_id"?: string, readonly "origin_product"?: "user_created" | "posthog_ai" | "signal_report", readonly "initial_permission_mode"?: TaskRunBootstrapCreateRequestInitialPermissionModeEnum | NullEnum, readonly "signal_report"?: string }
export const WarmTaskRequest = Schema.Struct({ "repository": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxLength(255, { "description": "Optional GitHub repository to clone, in `organization/repo` format (e.g. `posthog/posthog`)." }))])), "repositories": Schema.optionalKey(Schema.Array(Schema.String.check(Schema.isMaxLength(255))).annotate({ "description": "GitHub repositories to clone into the warm sandbox, each in `organization/repo` format." }).check(Schema.isMaxLength(3))), "github_integration": Schema.optionalKey(Schema.Union([Schema.Number.check(Schema.isInt()), Schema.Null]).annotate({ "description": "Primary key of the team's GitHub integration. Required when a repository is selected (it is what the sandbox clones with). Accepted without a repository too: the warm Run then boots with that integration's GitHub credentials, matching a repo-less create that carries it." })), "branch": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxLength(255, { "description": "Branch to check out in the warm sandbox. Defaults to the repository's default branch when omitted." }))])), "runtime_adapter": Schema.optionalKey(Schema.Union([RuntimeAdapterEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Agent runtime adapter to warm the sandbox on ('claude' or 'codex'). The warm Run starts the agent on this runtime so a matching submit reuses it; a submit selecting a different runtime falls through to a cold Run instead of reusing a mismatched warm session.\n\n* `claude` - claude\n* `codex` - codex" })), "model": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "LLM model identifier to warm the sandbox on. A submit selecting a different model won't reuse this warm Run." })), "reasoning_effort": Schema.optionalKey(Schema.Union([ReasoningEffortEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Reasoning effort to warm the sandbox on for models that expose an effort control.\n\n* `low` - low\n* `medium` - medium\n* `high` - high\n* `xhigh` - xhigh\n* `max` - max\n* `ultracode` - ultracode" })), "sandbox_environment_id": Schema.optionalKey(Schema.Union([Schema.String.annotate({ "description": "Optional sandbox environment to provision before the task is submitted.", "format": "uuid" })])), "custom_image_id": Schema.optionalKey(Schema.Union([Schema.String.annotate({ "description": "Optional custom base image to provision before the task is submitted; takes precedence over the environment's image.", "format": "uuid" })])), "origin_product": Schema.optionalKey(Schema.Literals(["user_created", "posthog_ai", "signal_report"]).annotate({ "description": "* `user_created` - user_created\n* `posthog_ai` - posthog_ai\n* `signal_report` - signal_report", "default": "user_created" })), "initial_permission_mode": Schema.optionalKey(Schema.Union([TaskRunBootstrapCreateRequestInitialPermissionModeEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Permission mode to boot the agent session on. Read at session construction, so it cannot be changed once the sandbox is warm — a submit selecting a different mode falls through to a cold Run. Omit to take the runtime's default.\n\n* `default` - default\n* `acceptEdits` - acceptEdits\n* `plan` - plan\n* `bypassPermissions` - bypassPermissions\n* `auto` - auto\n* `read-only` - read-only\n* `full-access` - full-access" })), "signal_report": Schema.optionalKey(Schema.Union([Schema.String.annotate({ "description": "Inbox report the warm discussion is about. Required with origin_product `signal_report`, where the warm Run boots repo-less and the submit that creates the report's discussion task activates it.", "format": "uuid" })])) }).annotate({ "description": "Request body for warming a full idling Run while composing a Code-app cloud task.\n\nCollection-level: no task exists yet at typing time. The warmer births a draft Task and an\ninteractive Run that boots and starts the agent, optionally cloning and checking out a repository,\nthen idles awaiting the first message. `github_integration` is a plain integration PK (an integer);\nthe view re-scopes it to the caller's team before use." })
