export const TaskRunArtifactResponse = Schema.Struct({ "id": Schema.optionalKey(Schema.String.annotate({ "description": "Stable identifier for the artifact within this run" })), "name": Schema.String.annotate({ "description": "Artifact file name" }), "type": Schema.String.annotate({ "description": "Artifact classification (plan, context, etc.)" }), "source": Schema.optionalKey(Schema.String.annotate({ "description": "Source of the artifact, such as agent_output or user_attachment" })), "size": Schema.optionalKey(Schema.Number.annotate({ "description": "Artifact size in bytes" }).check(Schema.isInt())), "content_type": Schema.optionalKey(Schema.String.annotate({ "description": "Optional MIME type" })), "metadata": Schema.optionalKey(Schema.Union([TaskRunSkillBundleMetadata, TaskRunPostHogReferenceMetadata], { mode: "oneOf" }).annotate({ "description": "Structured metadata for a skill bundle or a PostHog object reference." })), "storage_path": Schema.optionalKey(Schema.String.annotate({ "description": "S3 object key for file artifacts. Reference artifacts do not have one." })), "uploaded_at": Schema.String.annotate({ "description": "Timestamp when the artifact was uploaded or registered" }), "uploaded_by": Schema.optionalKey(Schema.Literals(["agent", "user"]).annotate({ "description": "* `agent` - agent\n* `user` - user" })), "uploaded_by_user_id": Schema.optionalKey(Schema.Number.annotate({ "description": "User id for an interactive user upload. Absent for agent uploads and legacy entries." }).check(Schema.isInt())), "dismissed_at": Schema.optionalKey(Schema.String.annotate({ "description": "Timestamp when a user dismissed the artifact. Absent while the artifact is shown." })), "url": Schema.optionalKey(Schema.String.annotate({ "description": "Stable download URL for the artifact. Populated on the finalize-upload response so the caller can link to the file; it redirects to a fresh presigned URL on each request and is not persisted on the manifest.", "format": "uri" })) })
