export const RepoOverview = Schema.Struct({ "cost_series": Schema.Array(CostPerMergeBucket).annotate({ "description": "CI cost per merged PR across the window, oldest first, zero-filled, bucketed by cost_series_granularity. Empty when the job-level source isn't synced or include_series=false." }), "time_to_green_series": Schema.Array(TimeToGreenBucket).annotate({ "description": "Median time-to-green (p50 wall clock for a PR push round to settle fully green) per bucket across the window, oldest first, bucketed by time_to_green_series_granularity. Empty buckets carry null; the whole series is empty when include_series=false." }), "success_rate_series": Schema.Array(PassRateBucket).annotate({ "description": "CI pass rate (conclusive runs that succeeded, all branches) per bucket across the window, oldest first, bucketed by success_rate_series_granularity. Skipped, cancelled, neutral, and action_required runs are excluded. Empty buckets carry null; the whole series is empty when include_series=false." }), "open_to_merge_series": Schema.Array(OpenToMergeBucket).annotate({ "description": "Median time-to-merge (p50 open_to_merge_seconds, bots/drafts excluded) per bucket across the window, oldest first, bucketed by open_to_merge_series_granularity. Empty buckets carry null; the whole series is empty when include_series=false." }), "delivery_pipeline": Schema.Struct({ "stages": Schema.Array(DeliveryStageTiming).annotate({ "description": "The legs, ordered open to merge. A leg with nothing observed still appears, with a zero pr_count and null timings. The leg medians do not sum to a cycle-time median: a median of sums is not a sum of medians." }), "merged_pr_count": Schema.Number.annotate({ "description": "PRs merged in the window with bots and drafts excluded. A narrower population than RepoOverview.merged_pr_count, which counts all authors." }).check(Schema.isInt()) }).annotate({ "description": "Where a change's wall-clock time goes on the way to production, over PRs merged in the window with bots and drafts excluded." }), "ready_to_merge_series": Schema.Array(ReadyToMergeBucket).annotate({ "description": "Median cycle time (p50 per-PR ready_to_merge_seconds, bots/drafts excluded) per bucket across the window, oldest first, bucketed by ready_to_merge_series_granularity. Empty buckets carry null; the whole series is empty when the issue-events table isn't synced or include_series=false, so fall back to open_to_merge_series." }), "run_count": Schema.Number.annotate({ "description": "Workflow runs started in the window, all branches and workflows." }).check(Schema.isInt()), "run_count_prev": Schema.Number.annotate({ "description": "Same count over the equal-length window immediately before date_from: the delta baseline." }).check(Schema.isInt()), "success_rate": Schema.Never, "success_rate_prev": Schema.Never, "rerun_cycles": Schema.Number.annotate({ "description": "Runs in the window that were a 2nd+ attempt (attempt > 1)." }).check(Schema.isInt()), "rerun_cycles_prev": Schema.Number.annotate({ "description": "Re-run cycles over the previous window." }).check(Schema.isInt()), "merged_pr_count": Schema.Number.annotate({ "description": "PRs merged in the window, all authors and bots included. billable_minutes and estimated_cost_usd cover every run in the window, including default-branch and unmerged PR runs, so dividing them by this count spreads all CI spend over the merges." }).check(Schema.isInt()), "merged_pr_count_prev": Schema.Number.annotate({ "description": "Merged-PR count over the previous window." }).check(Schema.isInt()), "median_open_to_merge_seconds": Schema.Never, "median_open_to_merge_seconds_prev": Schema.Never, "median_ready_to_merge_seconds": Schema.Never, "median_ready_to_merge_seconds_prev": Schema.Never, "billable_minutes": Schema.Never, "billable_minutes_prev": Schema.Never, "estimated_cost_usd": Schema.Never, "estimated_cost_usd_prev": Schema.Never, "cost_per_merge_usd": Schema.Never, "cost_per_merge_usd_prev": Schema.Never, "merge_queue_billable_minutes": Schema.Never, "merge_queue_billable_minutes_prev": Schema.Never, "merge_queue_merged_pr_count": Schema.Number.annotate({ "description": "PRs merged in the window with at least one corroborated merge-queue gate run: the population behind every merge_queue_* landing stat. All authors, bots included." }).check(Schema.isInt()), "merge_queue_merged_pr_count_prev": Schema.Number.annotate({ "description": "Queue-landed merges over the previous window." }).check(Schema.isInt()), "merge_queue_median_first_gate_to_merge_seconds": Schema.Never, "merge_queue_median_first_gate_to_merge_seconds_prev": Schema.Never, "merge_queue_p90_first_gate_to_merge_seconds": Schema.Never, "merge_queue_p90_first_gate_to_merge_seconds_prev": Schema.Never, "merge_queue_p95_first_gate_to_merge_seconds": Schema.Never, "merge_queue_p95_first_gate_to_merge_seconds_prev": Schema.Never, "merge_queue_p99_first_gate_to_merge_seconds": Schema.Never, "merge_queue_p99_first_gate_to_merge_seconds_prev": Schema.Never, "merge_queue_avg_attempts_per_merge": Schema.Never, "merge_queue_avg_attempts_per_merge_prev": Schema.Never, "merge_queue_multi_attempt_merge_share": Schema.Never, "merge_queue_multi_attempt_merge_share_prev": Schema.Never, "merge_queue_failed_gate_merge_share": Schema.Never, "merge_queue_failed_gate_merge_share_prev": Schema.Never, "merge_queue_trunk_available": Schema.Boolean.annotate({ "description": "Whether the team's TrunkIo warehouse source has the opt-in merge-queue endpoint synced and readable by the requesting user. When false, every merge_queue_failed_or_cancelled_* and merge_queue_skip_the_line_* field is null; fall back to merge_queue_failed_gate_merge_share." }), "merge_queue_failed_or_cancelled_share": Schema.Never, "merge_queue_failed_or_cancelled_share_prev": Schema.Never, "merge_queue_skip_the_line_count": Schema.Union([Schema.Number.check(Schema.isInt()), Schema.Null]).annotate({ "description": "Queue entries flagged skip-the-line (prioritized past the queue order) in the window, whatever state they reached. Null when the Trunk source isn't synced." }), "merge_queue_skip_the_line_count_prev": Schema.Union([Schema.Number.check(Schema.isInt()), Schema.Null]).annotate({ "description": "Skip-the-line entries over the previous window. Null when the Trunk source isn't synced." }), "median_time_to_green_seconds": Schema.Never, "median_time_to_green_seconds_prev": Schema.Never, "jobs_available": Schema.Boolean.annotate({ "description": "Whether the job-level source is synced (cost and queue figures exist)." }), "default_branch": Schema.String.annotate({ "description": "'master' or 'main', picked by observed run volume in the window." }), "cost_series_granularity": Schema.String.annotate({ "description": "Bucket width of the cost_series trend, chosen to fit the window: 'hour', 'day', or 'week'." }), "time_to_green_series_granularity": Schema.String.annotate({ "description": "Bucket width of the time_to_green_series trend: 'hour', 'day', or 'week'." }), "success_rate_series_granularity": Schema.String.annotate({ "description": "Bucket width of the success_rate_series trend: 'hour', 'day', or 'week'." }), "open_to_merge_series_granularity": Schema.String.annotate({ "description": "Bucket width of the open_to_merge_series trend: 'hour', 'day', or 'week'." }), "ready_to_merge_series_granularity": Schema.String.annotate({ "description": "Bucket width of the ready_to_merge_series trend: 'hour', 'day', or 'week'." }) })
export type PaginatedToleratedHashEntryList = { readonly "count": number, readonly "next"?: string, readonly "previous"?: string, readonly "results": ReadonlyArray<ToleratedHashEntry> }
export const PaginatedToleratedHashEntryList = Schema.Struct({ "count": Schema.Number.check(Schema.isInt()), "next": Schema.optionalKey(Schema.Union([Schema.String.annotate({ "format": "uri" })])), "previous": Schema.optionalKey(Schema.Union([Schema.String.annotate({ "format": "uri" })])), "results": Schema.Array(ToleratedHashEntry) })
export type TolerationPileups = { readonly "entries": ReadonlyArray<TolerationPileupEntry>, readonly "window_days": number, readonly "min_tolerations": number, readonly "min_automatic_tolerations": number | null, readonly "total": number, readonly "truncated": boolean, readonly "generated_at": string }
export const TolerationPileups = Schema.Struct({ "entries": Schema.Array(TolerationPileupEntry).annotate({ "description": "Matching snapshots, most manual tolerations first." }), "window_days": Schema.Number.annotate({ "description": "Length of the counting window in days that was applied." }).check(Schema.isInt()), "min_tolerations": Schema.Number.annotate({ "description": "Manual toleration threshold that was applied." }).check(Schema.isInt()), "min_automatic_tolerations": Schema.Union([Schema.Number.check(Schema.isInt()), Schema.Null]).annotate({ "description": "Automatic toleration threshold that was applied, or null when none was." }), "total": Schema.Number.annotate({ "description": "How many snapshots matched before `limit` was applied." }).check(Schema.isInt()), "truncated": Schema.Boolean.annotate({ "description": "True when `limit` cut the list short." }), "generated_at": Schema.String.annotate({ "description": "When the list was computed.", "format": "date-time" }) })
export type PatchedToolApprovalUpdate = { readonly "approval_state"?: ToolApprovalUpdateApprovalStateEnum }
export const PatchedToolApprovalUpdate = Schema.Struct({ "approval_state": Schema.optionalKey(ToolApprovalUpdateApprovalStateEnum) })
export type GatewayPoliciesUpsert = { readonly "scope_type"?: "team" | "member" | "agent", readonly "scope_user_id"?: number, readonly "scope_service_account_id"?: string, readonly "policies": ReadonlyArray<ToolPolicyEntry> }
export const GatewayPoliciesUpsert = Schema.Struct({ "scope_type": Schema.optionalKey(Schema.Literals(["team", "member", "agent"]).annotate({ "description": "* `team` - Team default\n* `member` - Member\n* `agent` - Agent", "default": "team" })), "scope_user_id": Schema.optionalKey(Schema.Number.annotate({ "description": "Member scope target. Defaults to the requesting user." }).check(Schema.isInt())), "scope_service_account_id": Schema.optionalKey(Schema.String.annotate({ "description": "Agent scope target. Required when scope_type is agent.", "format": "uuid" })), "policies": Schema.Array(ToolPolicyEntry).annotate({ "description": "Per-tool states to upsert for the scope. At most 1,000 entries per request." }).check(Schema.isMaxLength(1000)) })
export type ServiceAccountAccessUpdate = { readonly "gateway_server_id": string, readonly "enabled": boolean, readonly "scope"?: "personal" | "team", readonly "all"?: boolean, readonly "policies"?: ReadonlyArray<ToolPolicyEntry> }
export const ServiceAccountAccessUpdate = Schema.Struct({ "gateway_server_id": Schema.String.annotate({ "description": "Gateway server to share or stop sharing.", "format": "uuid" }), "enabled": Schema.Boolean.annotate({ "description": "True shares the caller's own connection with the agent, false removes the caller's share." }), "scope": Schema.optionalKey(Schema.Literals(["personal", "team"]).annotate({ "description": "* `personal` - Personal\n* `team` - Team", "default": "personal" })), "all": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Only valid with enabled=false. Removes every member's share of this server with this agent, along with the agent's tool policies for it. Project admins only.", "default": false })), "policies": Schema.optionalKey(Schema.Array(ToolPolicyEntry).annotate({ "description": "Optional agent-scope tool policies to set alongside the grant. At most 1,000 entries per request." }).check(Schema.isMaxLength(1000))) })
