export const WorkflowHealthItem = Schema.Struct({ "repo": Schema.Struct({ "provider": Schema.String.annotate({ "description": "Code host provider, e.g. 'github'." }), "owner": Schema.String.annotate({ "description": "Repository owner or organization." }), "name": Schema.String.annotate({ "description": "Repository name." }) }).annotate({ "description": "Repository the workflow runs in." }), "buckets": Schema.Array(WorkflowHealthBucket).annotate({ "description": "Run history across the whole window, oldest first, zero-filled, bucketed by granularity." }), "workflow_name": Schema.String.annotate({ "description": "GitHub Actions workflow name." }), "run_count": Schema.Number.annotate({ "description": "Total runs started in the window." }).check(Schema.isInt()), "successful_run_count": Schema.Number.annotate({ "description": "Completed runs with conclusion 'success'." }).check(Schema.isInt()), "conclusive_run_count": Schema.Number.annotate({ "description": "Completed runs that succeeded or ended in failure, timeout, startup failure, or staleness. This is the success_rate denominator." }).check(Schema.isInt()), "success_rate": Schema.Never, "p50_seconds": Schema.Never, "p95_seconds": Schema.Never, "last_failure_at": Schema.Union([Schema.String.annotate({ "description": "When the most recent decisive failure started, or null.", "format": "date-time" })]), "latest_run_failed": Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "description": "Whether the most recent completed run ended in failure, timeout, startup failure, or staleness. Null when no run has completed in the window. Powers the OK/RED status badge." }), "latest_run_conclusion": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Raw conclusion of the most recent completed run ('success', 'cancelled', 'skipped', ...), so a real pass can be told from a non-failure non-success. Null when none completed." }), "latest_run_id": Schema.Union([Schema.Number.check(Schema.isInt()), Schema.Null]), "latest_run_attempt": Schema.Union([Schema.Number.check(Schema.isInt()), Schema.Null]), "granularity": Schema.String.annotate({ "description": "Bucket width of the `buckets` series, chosen to fit the window: 'hour', 'day', or 'week'." }), "billable_minutes": Schema.optionalKey(Schema.Never), "estimated_cost_usd": Schema.optionalKey(Schema.Never), "rerun_cycles": Schema.optionalKey(Schema.Number.annotate({ "description": "Runs in the window that were a 2nd+ attempt - retry pressure, a flakiness proxy." }).check(Schema.isInt())), "success_rate_prev": Schema.optionalKey(Schema.Never), "percentile_run_count": Schema.optionalKey(Schema.Number.annotate({ "description": "Successful runs lasting at least 10 seconds. Zero when p50/p95 fall back to shorter successful runs." }).check(Schema.isInt())), "merge_queue_run_count": Schema.optionalKey(Schema.Number.annotate({ "description": "Runs on merge-queue gate branches (trunk-merge/**) in the window, counted regardless of branch or run_scope. Non-zero marks a workflow the queue runs before a merge lands, the closest available proxy for a required check." }).check(Schema.isInt())) })
