export type ExperimentSessionEventDeltaResponse = { readonly "cards": ReadonlyArray<ExperimentWatchCard>, readonly "variants": ReadonlyArray<ExperimentWatchVariant>, readonly "multiple_variant_persons": number, readonly "multiple_variant_handling": "exclude" | "first_seen", readonly "metric_events": ReadonlyArray<string>, readonly "date_from": string, readonly "date_to": string, readonly "filter_test_accounts": boolean, readonly "used_exposure_fallback": boolean, readonly "sessions_truncated": boolean, readonly "events_truncated": boolean, readonly "min_variant_persons": number, readonly "max_card_recordings": number, readonly "dropped_duplicate_cards": number, readonly "too_early": boolean, readonly "empty_reason": ExperimentWatchEmptyReasonEnum | NullEnum }
export const ExperimentSessionEventDeltaResponse = Schema.Struct({ "cards": Schema.Array(ExperimentWatchCard).annotate({ "description": "The shelf, strongest comparison first, then the variant's own rendering, then metric shortcuts. Events the variants can't be told apart on get no card at all rather than a weak one, so an empty shelf means no difference was big enough to be sure of, not that nothing was measured. Empty also takes the metric shortcuts with it: a shelf of shortcuts and no finding restates what the experiment's results already answer while reading as a finding, so it is withheld. Read empty_reason and say what it reports instead of presenting an empty shelf. Group by kind before presenting: a 'variant_only' card outranks every real difference by construction, and reading the shelf in order would report it as the headline." }), "variants": Schema.Array(ExperimentWatchVariant).annotate({ "description": "Every variant the analysis compares, with its population, in the flag's variant order. A variant the experiment excludes never appears here, because the analysis does not count it either, so read a missing key as excluded rather than as zero people." }), "multiple_variant_persons": Schema.Number.annotate({ "description": "People who saw more than one variant and were left out of every card. Always 0 when the experiment attributes such users to the variant they saw first." }).check(Schema.isInt()), "multiple_variant_handling": Schema.Literals(["exclude", "first_seen"]).annotate({ "description": "* `exclude` - exclude\n* `first_seen` - first_seen" }), "metric_events": Schema.Array(Schema.String).annotate({ "description": "The events the experiment's own metrics count. A card on one of these carries metric_name and must be read as pointing at the experiment's results, which measure the same event over the whole run window with the statistics that go with a result. Cards state no magnitude for exactly this reason, so never turn one into a claim about how the metric moved." }), "date_from": Schema.String.annotate({ "description": "When the earliest compared person was first exposed. The comparison takes the most recently exposed people, newest first, until it has as many as one comparison covers or their first sessions span 14 days of events, so on a busy experiment this is hours rather than days before date_to, and on an experiment that stopped enrolling it can be long before the experiment's end. Display this, not the experiment's own dates. Equal to date_to when nobody has been exposed yet.", "format": "date-time" }), "date_to": Schema.String.annotate({ "description": "One minute past the newest compared person's first exposure. Nobody first exposed between date_from and date_to was passed over, so the pair is a stretch of enrollment rather than a hull around scattered people. It bounds who was selected, not who was read: variants[].persons counts only those who then had a session. While an experiment runs this sits about an hour before now, because the newest hour of enrollment is held back until those people's first sessions have finished rather than read half-way through. Sessions reach past it, up to 24 hours after each person's own exposure, so this is not the end of the events that were read.", "format": "date-time" }), "filter_test_accounts": Schema.Boolean.annotate({ "description": "Whether the project's test-account filters were applied, following the experiment's exposure criteria, the same rule the experiment's recordings list uses." }), "used_exposure_fallback": Schema.Boolean.annotate({ "description": "Always false. The compared population is the exposed population the experiment's results count, matched to sessions by person, so no stamped-property fallback exists any more. The field stays for compatibility with existing readers." }), "sessions_truncated": Schema.Boolean.annotate({ "description": "True when more people were exposed than one comparison covers, so the most recently exposed were used and people exposed before date_from were left out. Every variant is still covered over the same stretch of enrollment. Named for the session ceiling it used to report; the name is kept for existing readers." }), "events_truncated": Schema.Boolean.annotate({ "description": "True when the project has more distinct event names in the window than one comparison can rank, so some were never considered." }), "min_variant_persons": Schema.Number.annotate({ "description": "How many exposed people a variant needs before it can be compared at all. Below it a variant's cards would be noise whatever the evidence bar allows." }).check(Schema.isInt()), "max_card_recordings": Schema.Number.annotate({ "description": "The most recordings one card can carry. A card whose recording_count equals this hit the ceiling, so report it as 'at least this many' rather than as a count." }).check(Schema.isInt()), "dropped_duplicate_cards": Schema.Number.annotate({ "description": "How many cards were removed because their recordings were already another card's on the same shelf. Nothing was lost: the recordings are all reachable through the cards that stayed." }).check(Schema.isInt()), "too_early": Schema.Boolean.annotate({ "description": "True when fewer than two variants have min_variant_persons exposed people, so no comparison exists and cards is empty. Show the variants' counts alongside it: an empty shelf presented without them would read as 'the variants behaved identically'. Read empty_reason and sessions_truncated before telling anyone to check back: this is also true when the variants are empty because the people exposed have no sessions we can see, which empty_reason reports as 'no_session_linked_exposures' and which more time fixes only while those people were exposed less than a day ago. And when sessions_truncated is true, only people exposed between date_from and date_to were compared, so more time helps only if more people are exposed within a stretch that long." }), "empty_reason": Schema.Union([ExperimentWatchEmptyReasonEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Why cards is empty, and null whenever cards is not empty. Report which of the four happened rather than reporting an empty shelf, because they ask different things of the reader. 'too_early': fewer than two variants have min_variant_persons exposed people, so nothing was compared yet. The answer can still change unless sessions_truncated is true, in which case only the people exposed between date_from and date_to were compared and more time helps only if more people are exposed within a stretch that long; a rollout split that changed during the run lands here too, and the experiment's exposure chart is where that shows. 'no_separation': the variants were compared and no event told them apart, which is a result rather than a failure. 'no_recordings': events did tell the variants apart, but no recording behind them can be opened, so the project's session replay sampling and retention are what decide whether this surface can ever show anything. 'no_session_linked_exposures': the people exposed between date_from and date_to had no session we can see since being exposed, looking up to 24 hours after each exposure, so there was nothing to compare. Two things reach this state, and they ask for different answers: no browser or mobile SDK is capturing events, because sessions exist nowhere else, or the exposed people have not come back. While the experiment runs the read stops at the time of the request, so people exposed less than a day ago are judged on less than a day and can still return. Check which one before telling anyone to check back, because more exposures captured the same way yield more of the same. Never fill an empty shelf with the experiment's metrics: shortcut cards to those metrics' events are withheld here for exactly that reason.\n\n* `too_early` - too_early\n* `no_separation` - no_separation\n* `no_recordings` - no_recordings\n* `no_session_linked_exposures` - no_session_linked_exposures" }) }).annotate({ "description": "The recordings worth watching for this experiment, grouped into cards.\n\nDescriptive, never a result: cards say where behavior visibly differed and hand over the\nrecordings, while the experiment's results measure its metrics over the whole run window and\nstate the magnitudes. Nothing here says a variant is winning." })
