export const LogsAnomalyScanSeries = Schema.Struct({ "severity": Schema.String.annotate({ "description": "Severity level of this log series (for example info, warn, error)." }), "stage": Schema.Union([LogsAnomalyBaselineStageEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Baseline stage reached by the end of the evaluation window. Null if no bucket was scored.\n\n* `insufficient` - insufficient\n* `cold_start` - cold_start\n* `developing` - developing\n* `mature` - mature" }), "tier": Schema.Union([TierEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Traffic tier at the end of the window, from a (0.5 or more records per second) down to d (below the detection floor of roughly 1 record per minute).\n\n* `a` - a\n* `b` - b\n* `c` - c\n* `d` - d" }), "history_start": Schema.Union([Schema.String.annotate({ "description": "Earliest bucket with data inside the fetched lookback.", "format": "date-time" })]), "limited_by": Schema.Union([LimitedByEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "What limited this series' baseline maturity, or null for a full baseline. series_history: data starts inside the lookback, because the series is young or a per-stream retention rule trimmed it (indistinguishable from the data). byte_budget and team_retention mirror the scan level constraints.\n\n* `series_history` - series_history\n* `team_retention` - team_retention\n* `byte_budget` - byte_budget" }), "buckets": Schema.Array(LogsAnomalyScanBucket).annotate({ "description": "Per bucket observed counts and expected bands across the evaluation window, for evidence charts." }) })
