export const LogsSeriesBandSeries = Schema.Struct({ "namespace": Schema.String.annotate({ "description": "Namespace of the emitting resource; empty when the logs carry none." }), "environment": Schema.String.annotate({ "description": "Deployment environment of the emitting resource; empty when the logs carry none." }), "severity": Schema.String.annotate({ "description": "Lowercased log severity of this series (for example info, error)." }), "total_count": Schema.Number.annotate({ "description": "Total observed log count over the window. Series are ordered by this, descending." }).check(Schema.isInt()), "baseline_weeks": Schema.Number.annotate({ "description": "Full weeks of history behind the band, 0 to 5. Four complete weeks are required: at least two for fitting and two separate weeks for calibration." }).check(Schema.isInt()), "history_start": Schema.String.annotate({ "description": "Start of sustained traffic inside the fetched lookback: the first bucket followed by a week with enough non-empty buckets. A stray earlier row does not move it. The window start when no traffic is sustained yet.", "format": "date-time" }), "band_ready_at": Schema.Union([Schema.String.annotate({ "description": "Earliest end of a rolling window of this length with four complete preceding weeks. Null when the band is ready. A fixed historical window does not gain history by waiting. Check the buckets' lower and upper values to determine whether a band is present.", "format": "date-time" })]), "interval_minutes": Schema.Number.annotate({ "description": "Grain of this series' buckets, in minutes. Equals the response interval_minutes unless the series was too sparse at that grain and was coarsened to the next rung it is dense enough to read at." }).check(Schema.isInt()), "coarsened_reason": Schema.Union([CoarsenedReasonEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Why this series was too thin to read at the requested grain, or null when it was not. sparse: fewer than 20% of its buckets held any records. quiet: its non-empty buckets averaged under 5 records. A series that fails every rung is returned at the coarsest one. A series that a coarser rung has no rows for, or that the request's time budget cannot refetch, keeps the requested grain and still carries its reason.\n\n* `sparse` - sparse\n* `quiet` - quiet" }), "buckets": Schema.Array(LogsSeriesBandBucket).annotate({ "description": "One entry per display bucket across the window at this series' interval_minutes, oldest first, zero-filled. A coarsened series' window is snapped to its grain, so it can end short of window_end." }) })
