export const ScannerScoutCreateResponse = Schema.Struct({ "created": Schema.Boolean.annotate({ "description": "False when a scout of this name already existed and the supplied config was applied to it." }), "config": Schema.Struct({ "id": Schema.String.annotate({ "readOnly": true, "format": "uuid" }), "skill_name": Schema.String.annotate({ "description": "The skill this config controls as a scout. Set at creation, not editable.", "readOnly": true }), "description": Schema.String.annotate({ "description": "Human-readable summary of what this scout investigates, sourced from the scout skill's `description` metadata. Use it for a quick steer on the scout's focus without loading the full skill body. Empty if the skill is not currently present on the team or carries no description.", "readOnly": true }), "display_name": Schema.optionalKey(Schema.String.annotate({ "description": "Name shown in the UI. Does not change the skill name. Leave blank to use the default name." }).check(Schema.isMaxLength(200))), "scout_origin": Schema.Literals(["canonical", "custom"]).annotate({ "description": "* `canonical` - canonical\n* `custom` - custom", "readOnly": true }), "scout_role": Schema.Literals(["specialist", "operational"]).annotate({ "description": "What this scout is to the harness: `specialist` for one that watches a product surface, or `operational` for one PostHog ships to watch the self-driving system itself. An operational scout is exempt from the inactivity sweep and from the enabled-scout cap, and is not a scout a project should delete. Always `specialist` for a custom scout.", "readOnly": true }), "deprecation": Schema.Union([ScoutDeprecation, Schema.Null], { mode: "oneOf" }).annotate({ "description": "Set when PostHog is retiring this scout, and null otherwise. Carries the phase, the reason to show, what replaces the scout, and when it stops running. Only a canonical scout the project has not edited is ever marked: a project's own copy keeps running and reads as null.", "readOnly": true }), "owners": Schema.Array(UserBasic).annotate({ "description": "Who answers for this scout, seed-creator first. Ownership is recorded on the scout's skill rather than on this config, so editing the skill or toggling the scout leaves it unchanged. Reports the scout files suggest these people as reviewers. Prefer this over `created_by`-style fields, which only say who last flipped a switch. Empty when nobody owns the scout, when the owners are no longer members with access to the project, or when the caller is a scout sandbox token: owners are member PII, and a scout reads them through the skill API instead.", "readOnly": true }), "enabled": Schema.Boolean.annotate({ "description": "Whether this scout runs on its schedule. Disabled scouts are skipped by the coordinator. Derived from `status`: true for `active` and `pending_pause`, false for the paused statuses.", "readOnly": true }), "status": Schema.Literals(["active", "pending_pause", "paused_by_system", "paused_by_user"]).annotate({ "description": "* `active` - Active\n* `pending_pause` - Pending pause\n* `paused_by_system` - Paused by system\n* `paused_by_user` - Paused by user", "readOnly": true }), "pause_reason": Schema.Union([SignalScoutConfigPauseReasonEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Why the system paused (or warned) this scout: `no_output` (it emitted nothing over the evaluation window), `ignored` (no person engaged with its reports — no view, rating, note, dismissal, or resolution), or `repeated_failures` (consecutive failed runs). Null unless `status` is `pending_pause` or `paused_by_system`.\n\n* `no_output` - No output\n* `ignored` - Ignored\n* `repeated_failures` - Repeated failures\n* `retired` - Retired", "readOnly": true }), "emit": Schema.Boolean.annotate({ "description": "Whether the scout writes findings to the inbox. False = dry-run: it runs and logs but emits nothing.", "readOnly": true }), "run_interval_minutes": Schema.Number.annotate({ "description": "Minutes between runs (30–43200). The scout runs once this interval has elapsed since its last run.", "readOnly": true }).check(Schema.isInt()).check(Schema.isGreaterThanOrEqualTo(30)).check(Schema.isLessThanOrEqualTo(43200)), "run_cron_schedule": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Optional five-field cron expression evaluated in the project timezone, e.g. '30 9 * * *'. Takes precedence over `run_interval_minutes` when set. Null means the rolling interval schedule.", "readOnly": true }), "output_destinations": Schema.Struct({ "slack": Schema.optionalKey(Schema.Union([SignalScoutSlackDestination, Schema.Null], { mode: "oneOf" }).annotate({ "description": "Slack destination for each emitted scout finding or report. Null or omitted disables Slack delivery." })), "webhook": Schema.optionalKey(Schema.Union([SignalScoutWebhookDestination, Schema.Null], { mode: "oneOf" }).annotate({ "description": "The CDP destination another product provisioned for this scout's reports. Null or omitted means no webhook. Unlike Slack, Signals does not deliver this itself: the reference lives here so the owning product can manage the destination's lifecycle." })) }).annotate({ "description": "Destinations that receive each finding or report this scout emits. Empty when none is configured.", "readOnly": true }), "structured_output_schema": Schema.Union([Schema.Struct({  }).annotate({ "description": "Optional JSON Schema (draft 2020-12) describing ONE structured record this scout produces via `scout-record-output` — e.g. a per-report quality judgment (`{\"type\": \"object\", \"properties\": {\"verdict\": {\"enum\": [\"good\", \"bad\", \"unsure\"]}, \"reason\": {\"type\": \"string\"}}, \"required\": [\"verdict\", \"reason\"]}`). The root must be `\"type\": \"object\"`. Setting a schema turns the structured-output channel on: the run prompt renders the schema and every submitted record is validated against it and recorded in the project as a `$scout_structured_output` event, queryable like any event. The channel also requires emit — a dry-run scout has nowhere to record to. Cardinality is the scout's call (one record per run, one per judged entity, ...). Null = channel off. Setting a schema requires skill-authoring authorization (the `llm_skill:write` scope and skill editor access) since the scout reads it verbatim in its prompt; clearing it needs only the config write. Records validate against the schema in force when the run was dispatched.", "readOnly": true })]), "network_access": Schema.Literals(["trusted", "full"]).annotate({ "description": "* `trusted` - Trusted domains only\n* `full` - Full", "readOnly": true }), "model": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Optional model id this scout's runs are pinned to, e.g. `claude-opus-4-5`. Must be one of the platform's agent models; an invalid id is rejected with the available ones listed. Null keeps the default model, chosen by the platform. Early access: the pin can only be set on projects enrolled in the scout model preview, and only takes effect there. Set null to clear it.", "readOnly": true }), "mcp_gateway_server_ids": Schema.Array(Schema.String.annotate({ "format": "uuid" })).annotate({ "description": "MCP gateway servers (by id) this scout's runs may use, chosen from the connections members shared to the whole team. Selection is per scout: an empty list gives the scout no MCP servers. Applies from the scout's next run.", "readOnly": true }).check(Schema.isMaxLength(100)), "repositories": Schema.optionalKey(Schema.Array(Schema.String.check(Schema.isMaxLength(255))).annotate({ "description": "GitHub repositories this scout clones into its sandbox, each in `organization/repo` format. Set them for a scout that reads code, so it can search the tree and run the project's own tests instead of reading files one API call at a time. Empty (the default) leaves the sandbox without a checkout. The scout's GitHub access stays read-only either way, so a repository listed here is never writable from a run. At most 10, each reachable through the project's GitHub connection. Applies from the scout's next run." }).check(Schema.isMaxLength(10))), "write_scopes": Schema.Array(Schema.String).annotate({ "description": "Extra write access granted to this one scout, as scope strings. The grantable set is `alert:write`, `annotation:write`, `dashboard:write`, `insight:write`, `llm_skill:write`, `replay_scanner:write`, `warehouse_table:write`, `warehouse_view:write`. Empty (the default) means the scout reads the project and writes only what every scout may write: notebooks, its findings, and its own memory. Each scope is project-wide and object-level, so a scout holding `dashboard:write` can update or delete any dashboard in the project, not only ones it made. Grant only what this scout maintains. Only the person the scout's runs act as (whoever authored it) or a project admin can set it, and a scoped API key must itself carry each scope it grants. A dry run (`emit=false`) never holds the grant. Applies from the scout's next run.", "readOnly": true }).check(Schema.isMaxLength(8)), "last_run_at": Schema.Union([Schema.String.annotate({ "description": "When the coordinator last dispatched this scout. Null if it has never run.", "readOnly": true, "format": "date-time" })]), "consecutive_failure_count": Schema.Number.annotate({ "description": "How many of this scout's runs have failed in a row. Back to 0 after a successful run or any config edit. At the failure limit the scout pauses itself (`status` becomes `paused_by_system` with `pause_reason` `repeated_failures`) and retries about once a day; a successful retry resumes it, and so does setting `enabled=true`.", "readOnly": true }).check(Schema.isInt()), "status_changed_at": Schema.Union([Schema.String.annotate({ "description": "When `status` last changed. For `pending_pause` this is when the warning was issued (an `ignored` warning pauses about a week later unless someone engages with the scout's reports — opening one counts; a `no_output` warning only flags the scout); for the paused statuses it is when the scout was paused. Null if the status never changed.", "readOnly": true, "format": "date-time" })]), "status_changed_by": Schema.Union([UserBasic, Schema.Null], { mode: "oneOf" }).annotate({ "description": "Who last moved `status`, when a person did it through this API. Null for a system transition such as an automatic pause, for a row whose status never changed, and for a caller that may not read member identities. Pair it with `status` to say who turned a scout off, instead of only when it went off.", "readOnly": true }), "auto_pause_exempt": Schema.Boolean.annotate({ "description": "Whether this scout is exempt from the inactivity sweep, meaning both the `ignored` pause and the `no_output` quiet warning. Set it on watchdog scouts whose value is staying quiet. Only ever set explicitly: re-enabling a swept scout instead grants a fresh grace window before the sweep may judge it again.", "readOnly": true }), "tags": Schema.optionalKey(Schema.Array(Schema.String).annotate({ "description": "Free-form labels for grouping the fleet, e.g. `[\"revenue\", \"on-call\"]`. Normalized to lowercase kebab-case (`On Call` and `on_call` both become `on-call`), deduped, and stored sorted; at most 10 tags, each at most 50 characters once normalized. Pass the full desired set — a write replaces the existing tags rather than merging into them. Filter the config list with the `tags` query parameter." })), "source_product": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "The product that stood this scout up for one of its own objects. Null when a person created it.", "readOnly": true }), "source_id": Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Id of the owning object in `source_product`, e.g. a Replay Vision scanner id.", "readOnly": true }), "created_at": Schema.String.annotate({ "readOnly": true, "format": "date-time" }), "updated_at": Schema.String.annotate({ "description": "When this config last changed: an edit through this API, or a status change the system made such as an automatic pause. A scheduled run does not bump it — the coordinator stamps `last_run_at` with a direct write — so this reads as when the scout was last tuned rather than when it last ran.", "readOnly": true, "format": "date-time" }) }).annotate({ "description": "Read shape for a per-(team, skill) scout config.\n\nOne row per scout skill on the team. The coordinator auto-creates a row\nwhen it discovers a scout skill; this serializer lets agents tune the row." }) }).annotate({ "description": "The scout that now watches this scanner." })
