export const TrendsFilter = Schema.Struct({ "aggregationAxisFormat": Schema.optionalKey(Schema.Union([AggregationAxisFormat, Schema.Null]).annotate({ "description": "Y-axis value formatter. Picks a human-friendly unit per value at render time without changing the underlying series values.\n\n- `numeric` (default): raw numbers, e.g. `1,234`.\n- `duration`: values are in seconds; rendered as friendly units per value (`45s`, `2m 12s`, `1h 4m`). Use this whenever the series is in seconds (latency, session length, time-to-event) instead of dividing in `formula` to force minutes or hours.\n- `duration_ms`: values are in milliseconds; rendered as friendly units (`850ms`, `1.5s`, `1m 4s`).\n- `percentage`: values are already in the 0-100 range; appends `%`.\n- `percentage_scaled`: values are a 0-1 ratio; multiplied and rendered as `%`.\n- `currency`: values are in the project's base currency (set in project settings, defaults to USD); rendered with that currency symbol. For values pinned to a specific currency regardless of project base (e.g. `$ai_total_cost_usd` is always USD), use `aggregationAxisPrefix` instead.\n- `short`: compact notation for large counts (`1.2K`, `3.4M`).", "default": "numeric" })), "aggregationAxisPostfix": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "title": "Aggregationaxispostfix", "description": "Literal suffix applied to every value (e.g. ` req`). Reserve for units that `aggregationAxisFormat` cannot express. Do not use ` mins`, ` s`, ` ms`, `%` etc. — pick the matching `aggregationAxisFormat` instead so the underlying values stay numerically correct for breakdowns, formulas, and alerts. Include any leading space yourself.", "default": null })), "aggregationAxisPrefix": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "title": "Aggregationaxisprefix", "description": "Literal prefix applied to every value (e.g. `$`). Use to pin a unit or currency symbol that does not depend on `aggregationAxisFormat` — for example, when values are denominated in a fixed currency regardless of the project's base currency. Include any trailing space yourself.", "default": null })), "annotationsScope": Schema.optionalKey(Schema.Union([AnnotationScope, Schema.Null]).annotate({ "description": "Render only annotations with this scope. Unset renders every scope.", "default": null })), "breakdown_histogram_bin_count": Schema.optionalKey(Schema.Union([Schema.Number.check(Schema.isFinite()), Schema.Null]).annotate({ "title": "Breakdown Histogram Bin Count", "default": null })), "chartStyle": Schema.optionalKey(Schema.Union([ChartStyle, Schema.Null]).annotate({ "description": "Chart rendering style overrides (line shape).", "default": null })), "confidenceLevel": Schema.optionalKey(Schema.Union([Schema.Number.check(Schema.isFinite()), Schema.Null]).annotate({ "title": "Confidencelevel", "default": null })), "decimalPlaces": Schema.optionalKey(Schema.Union([Schema.Number.check(Schema.isFinite()), Schema.Null]).annotate({ "title": "Decimalplaces", "description": "Maximum number of decimal places shown. 1 or 2 is usually right for percentages and currency.", "default": null })), "detailedResultsAggregationType": Schema.optionalKey(Schema.Union([DetailedResultsAggregationType, Schema.Null]).annotate({ "description": "detailed results table", "default": null })), "display": Schema.optionalKey(Schema.Union([ChartDisplayType, Schema.Null]).annotate({ "default": "ActionsLineGraph" })), "excludeBoxPlotOutliers": Schema.optionalKey(Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "title": "Excludeboxplotoutliers", "default": true })), "formula": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "title": "Formula", "default": null })), "formulaNodes": Schema.optionalKey(Schema.Union([Schema.Array(TrendsFormulaNode), Schema.Null]).annotate({ "title": "Formulanodes", "description": "List of formulas with optional custom names. Takes precedence over formula/formulas if set.", "default": null })), "formulas": Schema.optionalKey(Schema.Union([Schema.Array(Schema.String), Schema.Null]).annotate({ "title": "Formulas", "default": null })), "goalLines": Schema.optionalKey(Schema.Union([Schema.Array(GoalLine), Schema.Null]).annotate({ "title": "Goallines", "description": "Goal Lines", "default": null })), "hiddenLegendIndexes": Schema.optionalKey(Schema.Union([Schema.Array(Schema.Number.check(Schema.isInt())), Schema.Null]).annotate({ "title": "Hiddenlegendindexes", "default": null })), "hideWeekends": Schema.optionalKey(Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "title": "Hideweekends", "description": "Ignored. Superseded by `dateRange.daysOfWeek`, which excludes the days from the query instead of only hiding their buckets. Still accepted so existing API clients keep working.", "default": false })), "legendPosition": Schema.optionalKey(Schema.Union([LegendPosition, Schema.Null]).annotate({ "description": "Where the in-chart legend sits relative to the plot. Only applies to the in-chart legend.", "default": "bottom" })), "metricChangeDecreaseColor": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "title": "Metricchangedecreasecolor", "description": "Metric display: change pill color when the metric decreased. Defaults to red.", "default": null })), "metricChangeIncreaseColor": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "title": "Metricchangeincreasecolor", "description": "Metric display: change pill color when the metric increased. Defaults to green.", "default": null })), "metricColorByDirection": Schema.optionalKey(Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "title": "Metriccolorbydirection", "description": "Metric display: color the sparkline by whether the metric increased or decreased.", "default": false })), "metricLineDecreaseColor": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "title": "Metriclinedecreasecolor", "description": "Metric display: line color when the metric decreased. Defaults to red.", "default": null })), "metricLineIncreaseColor": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "title": "Metriclineincreasecolor", "description": "Metric display: line color when the metric increased. Defaults to green.", "default": null })), "metricShowChange": Schema.optionalKey(Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "title": "Metricshowchange", "description": "Show the period-over-period change pill on the Metric display.", "default": true })), "metricSummary": Schema.optionalKey(Schema.Union([MetricSummary, Schema.Null]).annotate({ "description": "Metric display: which summary the resting headline shows — the period total, the average, or the latest point. Hovering the sparkline always shows the hovered point's value. Also drives the change pill: total/average compare against the previous period when \"compare to previous\" is on; latest compares first→last of the series.", "default": "total" })), "minDecimalPlaces": Schema.optionalKey(Schema.Union([Schema.Number.check(Schema.isFinite()), Schema.Null]).annotate({ "title": "Mindecimalplaces", "default": null })), "movingAverageIntervals": Schema.optionalKey(Schema.Union([Schema.Number.check(Schema.isFinite()), Schema.Null]).annotate({ "title": "Movingaverageintervals", "default": null })), "resultCustomizationBy": Schema.optionalKey(Schema.Union([ResultCustomizationBy, Schema.Null]).annotate({ "description": "Wether result datasets are associated by their values or by their order.", "default": "value" })), "resultCustomizations": Schema.optionalKey(Schema.Union([Schema.Record(Schema.String, ResultCustomizationByValue), Schema.Record(Schema.String, ResultCustomizationByPosition), Schema.Null]).annotate({ "title": "Resultcustomizations", "description": "Customizations for the appearance of result datasets.", "default": null })), "showAlertThresholdLines": Schema.optionalKey(Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "title": "Showalertthresholdlines", "default": false })), "showAnnotations": Schema.optionalKey(Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "title": "Showannotations", "default": true })), "showConfidenceIntervals": Schema.optionalKey(Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "title": "Showconfidenceintervals", "default": null })), "showLabelsOnSeries": Schema.optionalKey(Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "title": "Showlabelsonseries", "default": null })), "showLegend": Schema.optionalKey(Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "title": "Showlegend", "default": false })), "showMovingAverage": Schema.optionalKey(Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "title": "Showmovingaverage", "default": null })), "showMultipleYAxes": Schema.optionalKey(Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "title": "Showmultipleyaxes", "default": false })), "showPercentStackView": Schema.optionalKey(Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "title": "Showpercentstackview", "default": false })), "showTrendLines": Schema.optionalKey(Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "title": "Showtrendlines", "default": null })), "showValuesOnSeries": Schema.optionalKey(Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "title": "Showvaluesonseries", "default": false })), "smoothingIntervals": Schema.optionalKey(Schema.Union([Schema.Number.check(Schema.isInt()), Schema.Null]).annotate({ "title": "Smoothingintervals", "default": 1 })), "stackBreakdownValues": Schema.optionalKey(Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "title": "Stackbreakdownvalues", "description": "On the horizontal bar-value chart, stack a series' breakdown values into a single bar instead of rendering one bar per breakdown value.", "default": false })), "xAxisLabel": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "title": "Xaxislabel", "description": "Custom label rendered under the X axis.", "default": null })), "yAxisLabel": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "title": "Yaxislabel", "description": "Custom label rendered alongside the Y axis.", "default": null })), "yAxisMax": Schema.optionalKey(Schema.Union([Schema.Number.check(Schema.isFinite()), Schema.Null]).annotate({ "title": "Yaxismax", "description": "Pins the top of the y-axis; unset means automatic. Ignored in the same cases as `yAxisStartAtZero`, and when `yAxisMin` is not below it.", "default": null })), "yAxisMin": Schema.optionalKey(Schema.Union([Schema.Number.check(Schema.isFinite()), Schema.Null]).annotate({ "title": "Yaxismin", "description": "Pins the bottom of the y-axis; unset means automatic. Ignored in the same cases as `yAxisStartAtZero`, while it is on, and when not below `yAxisMax`.", "default": null })), "yAxisScaleType": Schema.optionalKey(Schema.Union([YAxisScaleType, Schema.Null]).annotate({ "default": "linear" })), "yAxisStartAtZero": Schema.optionalKey(Schema.Union([Schema.Boolean, Schema.Null]).annotate({ "title": "Yaxisstartatzero", "description": "Y-axis baseline. When false the axis floats to the data range instead of starting at zero. Ignored on bar displays (bars always draw from zero), on a logarithmic scale, and while showing percentages.", "default": true })) }).annotate({ "title": "TrendsFilter" })
