export const EmitReportRequest = Schema.Struct({ "title": Schema.String.annotate({ "description": "One-line report title the inbox shows. Conventional-commit style (`type(scope): description`, e.g. `fix(insights): missing series color`) renders with type/scope styling." }).check(Schema.isMaxLength(300)), "summary": Schema.String.annotate({ "description": "The report body the inbox shows. Markdown is supported (headings, lists, code, links; images are not rendered). Lead with one plain declarative sentence — the inbox card uses your first line verbatim as the headline (~140 chars, emphasis stripped), then renders the full markdown in the detail view. A heading, or a bold label on a line of its own with a blank line above it, marks a section that a threaded Slack delivery splits into its own reply." }), "evidence": Schema.Array(ReportEvidence).annotate({ "description": "The observations backing the report — each becomes a bound signal. At least one." }).check(Schema.isMinLength(1)), "actionability_explanation": Schema.String.annotate({ "description": "2-3 sentence evidence-grounded justification for the actionability call below." }), "actionability": Schema.Literals(["immediately_actionable", "requires_human_input", "not_actionable"]).annotate({ "description": "* `immediately_actionable` - immediately_actionable\n* `requires_human_input` - requires_human_input\n* `not_actionable` - not_actionable" }), "already_addressed": Schema.optionalKey(Schema.Boolean.annotate({ "description": "Whether the issue is already being handled — fixed in recent changes, or with a fix in flight (an open PR, a recently active branch, an assigned / in-progress issue or agent task). Gates autostart, so a wrong `false` opens a duplicate PR. Tracked separately.", "default": false })), "repository": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "Optional repo for opening a draft PR, by autostart or by a person from the inbox. Pass `owner/repo` whenever you can say where a fix would land. Omit the field when you can't, which triggers free-form selection across the team's repos (the slow path on a many-repo team). Keep the `NO_REPO` sentinel for the rare report where nothing under version control could change, since a skill body, a config file, or a doc still lives in a repo." })), "priority": Schema.optionalKey(Schema.Union([AutonomyPriorityEnum, NullEnum], { mode: "oneOf" }).annotate({ "description": "Optional priority (`P0`-`P4`). Required for autostart; pair with `priority_explanation`.\n\n* `P0` - P0\n* `P1` - P1\n* `P2` - P2\n* `P3` - P3\n* `P4` - P4" })), "priority_explanation": Schema.optionalKey(Schema.Union([Schema.String, Schema.Null]).annotate({ "description": "2-3 sentence justification for `priority`. Required when `priority` is set." })), "suggested_reviewers": Schema.optionalKey(Schema.Array(SuggestedReviewer).annotate({ "description": "Optional reviewers to route the report to (each a `github_login` and/or `user_uuid`). This is the primary way a report reaches a human — the inbox floats a reviewer's own reports to the top of their inbox even when no PR is involved — so set it whenever you can name a plausible owner. It also gates autostart: a PR opens only if at least one reviewer clears their autonomy threshold." }).check(Schema.isMaxLength(10))), "charts": Schema.optionalKey(Schema.Array(ReportChart).annotate({ "description": "Optional charts to attach to the report — the inbox renders them inline, so a metric move is something the reader sees rather than a number they take on trust. Attach one whenever the finding rests on a trend, a spike, or a comparison you already queried." }).check(Schema.isMaxLength(20))), "metrics": Schema.optionalKey(Schema.Array(ReportMetricWrite).annotate({ "description": "Optional typed impact measurements. Use one primary metric for the key observation and supporting metrics for users, sessions, occurrences, conversion, latency, or revenue. Every metric requires a bounded live InsightVizNode/TrendsQuery built only from EventsNode or ActionsNode sources and capped at 1,000 estimated longitudinal points. Consumers derive BoldNumber and ActionsBar shapes. A value/value_at snapshot is an optional cached fallback. Affected users must use one series with `math: dau`. Snapshot-only/queryless payloads are invalid; legacy rows of that shape are always redacted." }).check(Schema.isMaxLength(6))), "suggested_prompts": Schema.optionalKey(Schema.Array(Schema.String.check(Schema.isMaxLength(200))).annotate({ "description": "Optional follow-up prompts to offer above the report's `Ask AI` box: questions to ask, or next-step actions to request (e.g. carrying out the report's recommendation). The reader clicks one to fill the box with it, then sends or edits it. Write the prompts your own research left open, phrased as the reader would send them." }).check(Schema.isMaxLength(3))), "idempotency_key": Schema.optionalKey(Schema.Union([Schema.String.check(Schema.isMaxLength(200, { "description": "Optional name for this emission, unique within the run. Reuse it verbatim to retry a call whose outcome you don't know (a timeout, a dropped connection): the retry returns the report the first call authored, with `idempotent_replay` true, instead of a second report. Omit it and the report's own content is the key, which covers a retry of the identical call — pass one when a retry might reword the report." }))])) }).annotate({ "description": "Request body for `emit-report`. Run attribution is taken from the URL path." })
